/* Contenido de «Diplomado en Liderazgo para Mandos Medios». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("d-liderazgo",{"l":{"d-liderazgo-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar, con claridad.</b> Este es un <b>diplomado libre de capacitación</b>: al terminarlo recibes una <b>constancia de Instituto Mara</b>. <b>No</b> es un título ni un documento oficial de la SEP, y <b>no</b> es una certificación de competencias de CONOCER. Su valor está en lo que vas a poder hacer con tu equipo desde el lunes."},{"tipo":"texto","texto":"Un <b>mando medio</b> es la persona que está entre la dirección y la operación: supervisor de línea, jefe de turno, coordinador de call center, gerente de piso, jefa de enfermeras de un servicio. Recibe metas desde arriba y tiene que convertirlas en trabajo diario de un equipo. Casi siempre llegas al puesto porque eras <b>muy bueno haciendo el trabajo</b>; el reto es que ahora tu trabajo es <b>lograr resultados a través de otros</b>."},{"tipo":"tabla","titulo":"Lo que cambia al subir de puesto","encabezados":["Antes (operativo)","Ahora (mando medio)"],"filas":[["Te medían por lo que tú producías","Te miden por lo que produce tu equipo"],["Resolvías los problemas con tus manos","Enseñas y organizas para que otros los resuelvan"],["Tu agenda la ponía tu jefe","Repartes tu tiempo entre equipo, jefe, otras áreas y pendientes"],["Opinabas sobre las decisiones","Tomas decisiones y respondes por ellas"],["Eras parte del grupo de amigos","Sigues siendo cercano, pero con otro papel"]]},{"tipo":"texto","texto":"Ejemplo: Rogelio era el mejor operador de inyección en una planta de autopartes en Silao. Lo ascendieron a supervisor del turno B. La primera semana se la pasó arreglando moldes él mismo «porque así es más rápido». Resultado: la línea funcionó, pero nadie aprendió, llegó tarde a la junta con producción y no revisó el ausentismo. Hacer el trabajo de tu gente se siente productivo, pero te quita el tiempo de hacer el tuyo."},{"tipo":"lista","items":["<b>Hacia abajo:</b> dar dirección, organizar, desarrollar y cuidar a tu equipo.","<b>Hacia arriba:</b> informar a tiempo, proponer soluciones y traducir las metas en planes realistas.","<b>Hacia los lados:</b> coordinarte con otras áreas (calidad, mantenimiento, almacén, RH).","<b>Contigo:</b> administrar tu tiempo, tus emociones y tu aprendizaje."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"A un mando medio se le mide principalmente por…","ops":["Los resultados de su equipo","Lo que produce con sus propias manos","Lo simpático que cae"],"correcta":0,"explica":"Tu aportación ahora es multiplicar el trabajo de otros."},{"p":"Rogelio arregla los moldes él mismo todos los días. El riesgo principal es…","ops":["Que la línea produzca más","Ninguno, es buen ejemplo","Que nadie aprenda y descuide su propio trabajo de supervisor"],"correcta":2,"explica":"Una vez está bien; como hábito, te vuelves el cuello de botella."}]},{"tipo":"relacionar","rotulo":"¿Hacia dónde va cada tarea?","pares":[["Explicar la meta del día al arranque del turno","Hacia abajo"],["Avisar a tu gerente que un pedido se va a retrasar","Hacia arriba"],["Acordar con mantenimiento el paro de una máquina","Hacia los lados"],["Bloquear media hora para planear la semana","Contigo"]]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el mejor vendedor que se volvió el peor jefe</b><br>Ernesto era el mejor vendedor de una agencia de autos en Aguascalientes. Lo nombraron gerente de piso. Siguió vendiendo él mismo, les «quitaba» los clientes grandes a su equipo para cerrar más rápido y no tenía tiempo de capacitar a nadie. A los seis meses, dos vendedores renunciaron y las ventas del equipo bajaron.<br>El mando medio logra resultados a través de su equipo. Su trabajo va en cuatro direcciones: equipo, jefe, otras áreas y él mismo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál fue el error principal de Ernesto?","ops":["Ser amable","Vender demasiado","Seguir actuando como el mejor operativo en lugar de desarrollar a su equipo"],"correcta":2,"explica":"Su resultado ahora es el del equipo, no el suyo."},{"p":"¿Qué debió hacer con los clientes grandes?","ops":["Cerrarlos él siempre","Dejarlos ir","Acompañar a un vendedor en el cierre para enseñarle"],"correcta":2,"explica":"Así el equipo aprende y él gana tiempo después."},{"p":"La relación con otras áreas (crédito, taller) es parte de…","ops":["lo que no le toca","su trabajo como mando medio","el trabajo de su jefe únicamente"],"correcta":1,"explica":"El mando medio conecta en cuatro direcciones."}]},{"tipo":"comparar","titulo":"Cómo se oye en el piso de ventas","mal":"«Déjame a mí ese cliente, yo lo cierro más rápido.»","bien":"«Vamos juntos con ese cliente. Tú llevas la plática y yo te apoyo en la negociación; después lo platicamos.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe cómo reparte hoy su tiempo un jefe que conozcas (o tú) entre equipo, jefe, otras áreas y trabajo propio, y cómo debería repartirlo.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe tres tareas que haces (o hacía ese jefe) como operativo y que deberían pasar al equipo, y a quién.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Mi reparto de tiempo como jefe","texto":"MI SEMANA COMO JEFE\nDirección | % de tiempo hoy | % ideal | Qué cambiaré\nEquipo (instruir, acompañar, retroalimentar) | [ ] | [ ] | [ ]\nMi jefe (informar, acordar) | [ ] | [ ] | [ ]\nOtras áreas (coordinar) | [ ] | [ ] | [ ]\nYo (aprender, planear, cuidarme) | [ ] | [ ] | [ ]\nTrabajo operativo que debo soltar: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["El mando medio logra resultados a través de su equipo.","Tu trabajo va en cuatro direcciones: equipo, jefe, otras áreas y tú.","Este diplomado da constancia de Instituto Mara, no documento SEP ni CONOCER."]}],"d-liderazgo-m1-l2":[{"tipo":"texto","texto":"El nombramiento te da <b>autoridad formal</b>: puedes asignar tareas, autorizar permisos, firmar reportes. Pero eso no garantiza que la gente te siga con ganas. El <b>liderazgo</b> es la capacidad de influir en otros para que trabajen hacia un objetivo común, y se gana con conducta: cumplir lo que prometes, ser justo, saber del trabajo y tratar con respeto."},{"tipo":"comparar","titulo":"Autoridad sola vs liderazgo","malTitulo":"Solo autoridad","mal":"«Aquí se hace así porque lo digo yo. Si no les gusta, ahí está la puerta.» La gente obedece mientras el jefe está presente y hace lo mínimo cuando se va.","bienTitulo":"Autoridad con liderazgo","bien":"«Necesitamos cerrar los 300 pedidos antes de las 6 porque sale el tráiler a Monterrey. Así lo vamos a repartir. ¿Qué ven que nos pueda atorar?» La gente entiende el porqué y ayuda a resolver."},{"tipo":"tabla","titulo":"Estilos de liderazgo comunes","encabezados":["Estilo","Cómo se ve","Cuándo sirve","Riesgo si abusas"],"filas":[["Autoritario o directivo","El jefe decide y ordena","Emergencias, seguridad, personal nuevo","Equipo pasivo y con miedo"],["Democrático o participativo","Consulta al equipo antes de decidir","Mejoras de proceso, cambios que afectan a todos","Lentitud cuando urge decidir"],["Delegativo o «laissez-faire»","Deja que el equipo decida","Gente experta y comprometida","Abandono: nadie sabe qué se espera"],["Coach o formador","Enseña, pregunta, acompaña","Desarrollar a alguien con potencial","Poco útil si hay prisa extrema"]],"nota":"Ningún estilo es bueno siempre. El buen jefe cambia de estilo según la situación y la persona."},{"tipo":"texto","texto":"Ejemplo: en una sucursal bancaria de Querétaro, la gerente Mariana usa estilo directivo cuando hay un simulacro de sismo («salgan por la puerta 2, ya»), participativo cuando reorganiza los horarios de caja y delegativo con su ejecutivo más experimentado, que ya maneja solo la cartera de pymes."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El liderazgo se diferencia de la autoridad en que…","ops":["Solo lo tienen los directores","Se gana con conducta, no con el nombramiento","Viene en el contrato"],"correcta":1,"explica":"La autoridad te la dan; el liderazgo te lo ganas."},{"p":"Hay una fuga de gas en el almacén. El estilo adecuado es…","ops":["Directivo","Delegativo","Participativo con votación"],"correcta":0,"explica":"En una emergencia no se consulta: se da una instrucción clara."},{"p":"Tu técnico con 15 años de experiencia propone cómo organizar el mantenimiento preventivo. Conviene…","ops":["Ordenarle paso a paso","Ignorarlo","Delegarle la organización con seguimiento"],"correcta":2}]},{"tipo":"tarjetas","rotulo":"Fuentes de influencia de un jefe","tarjetas":[{"frente":"Autoridad del puesto","reverso":"Viene del nombramiento. Sirve para lo formal, pero se desgasta si es lo único que usas."},{"frente":"Conocimiento","reverso":"La gente te sigue porque sabes resolver. Cuídalo: actualízate."},{"frente":"Ejemplo","reverso":"Si llegas a tiempo y usas el equipo de protección, puedes pedirlo."},{"frente":"Relación","reverso":"Confianza construida con trato justo y cumplir lo que dices."}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «aquí se hace lo que yo digo»</b><br>La nueva supervisora de una línea de producción en Ramos Arizpe llegó diciendo: «Aquí se hace lo que yo digo porque yo soy la supervisora». Al principio obedecían, pero nadie le avisaba de los problemas y hacían lo mínimo. En la línea de al lado, un supervisor sin tanta antigüedad lograba que su equipo le propusiera mejoras.<br>La autoridad te la da el puesto; el liderazgo te lo ganas con conducta. Hay estilos directivo, participativo, delegativo y coach, y ninguno sirve siempre."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué le da la autoridad a la supervisora?","ops":["El puesto","El respeto del equipo","Su experiencia"],"correcta":0,"explica":"La autoridad es formal; el liderazgo es ganado."},{"p":"¿Cuándo sí conviene un estilo directivo?","ops":["Siempre","Nunca","En una emergencia o con alguien que no sabe hacer la tarea"],"correcta":2,"explica":"El estilo se elige según la situación."},{"p":"¿Qué gana el supervisor de al lado?","ops":["Un mejor sueldo","Liderazgo: su equipo lo sigue por su conducta","Autoridad formal"],"correcta":1,"explica":"El equipo propone porque confía."}]},{"tipo":"comparar","titulo":"Cómo se oye el primer día","mal":"«Aquí se hace lo que yo digo porque yo soy la supervisora.»","bien":"«Mi trabajo es que la línea cumpla y que ustedes tengan lo que necesitan. Esta semana quiero escucharlos: ¿qué les estorba para trabajar bien?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Recuerda al mejor y al peor jefe que hayas tenido. Escribe tres conductas concretas de cada uno y qué efecto tenían en ti.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe qué estilo de liderazgo usas más y en qué situación te convendría usar otro.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Estilos y cuándo usarlos","texto":"ESTILOS DE LIDERAZGO\nDirectivo: dices qué, cómo y cuándo. Úsalo: emergencias, persona nueva en la tarea.\nParticipativo: decides con el equipo. Úsalo: cambios que afectan a todos.\nDelegativo: das el resultado y la autonomía. Úsalo: personas expertas y comprometidas.\nCoach: preguntas y acompañas para que aprenda. Úsalo: personas con potencial.\n\nMi estilo más frecuente: [ ]\nSituación donde debo cambiarlo: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["La autoridad te la da el puesto; el liderazgo te lo ganas con conducta.","Estilos: directivo, participativo, delegativo y coach.","Ninguno sirve siempre: se elige según la situación y la persona."]}],"d-liderazgo-m1-l3":[{"tipo":"texto","texto":"El <b>modelo de liderazgo situacional</b> lo propusieron <b>Paul Hersey y Ken Blanchard</b> a finales de los años sesenta. Su idea central: <b>no hay un estilo único</b>; el estilo correcto depende de la <b>madurez o disposición</b> del colaborador <i>para esa tarea</i>, es decir, qué tan <b>capaz</b> (sabe hacerlo) y qué tan <b>dispuesto</b> (quiere y se siente seguro) está."},{"tipo":"texto","texto":"El jefe combina dos tipos de conducta: <b>conducta de tarea</b> (decir qué, cómo y cuándo; supervisar de cerca) y <b>conducta de relación</b> (escuchar, animar, explicar el porqué, involucrar). Según cuánto de cada una uses, salen cuatro estilos."},{"tipo":"tabla","titulo":"Los cuatro estilos del modelo","encabezados":["Estilo","Tarea / relación","Para quién","Ejemplo"],"filas":[["E1 Dirigir (ordenar)","Mucha tarea, poca relación","No sabe hacerlo y está inseguro o desmotivado","Cajero nuevo el primer día: le enseñas paso a paso el arqueo"],["E2 Persuadir (entrenar)","Mucha tarea, mucha relación","No sabe todavía, pero tiene ganas","Agente de call center con 3 semanas: le explicas y lo animas"],["E3 Participar (apoyar)","Poca tarea, mucha relación","Sabe hacerlo, pero duda o perdió motivación","Enfermera con experiencia insegura en un equipo nuevo: la escuchas y decides con ella"],["E4 Delegar","Poca tarea, poca relación","Sabe hacerlo y quiere hacerlo","Montacarguista experto: le das el objetivo y revisas al final"]],"nota":"La misma persona puede estar en distintos niveles según la tarea: un vendedor estrella puede ser principiante en el nuevo sistema de inventarios."},{"tipo":"relacionar","rotulo":"¿Qué estilo le toca?","pares":[["Practicante que nunca ha usado la báscula de recibo","Dirigir"],["Nuevo auxiliar entusiasta que aún comete errores","Persuadir"],["Operadora experta que anda desanimada tras un regaño injusto","Participar"],["Jefe de almacén con años de experiencia y buenos resultados","Delegar"]]},{"tipo":"practica","rotulo":"Caso: Karla, jefa de piso en un autoservicio de León","preguntas":[{"p":"Luis lleva 6 años en perecederos y siempre cumple. Karla le revisa cada caja y le dice cómo acomodar. ¿Qué pasa?","ops":["Debería regañarlo más","Lo sobredirige: le convendría delegar","Aplica bien el modelo"],"correcta":1,"explica":"Dirigir a alguien capaz y dispuesto lo desmotiva: siente que no confías en él."},{"p":"A Sofía, recién llegada, Karla le dice «tú ya sabes, acomoda la bodega». Sofía se equivoca todo el día. ¿Qué faltó?","ops":["Dirigir o persuadir: dar instrucciones claras y acompañar","Delegar más","Nada, así se aprende"],"correcta":0,"explica":"Delegar a quien no sabe es abandonarlo."},{"p":"Con el tiempo, Sofía aprende. Karla debería…","ops":["Seguir dirigiéndola igual siempre","Dejar de hablar con ella","Ir soltando control y pasar a apoyar y luego delegar"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa el modelo","items":[{"frase":"El estilo depende de qué tan capaz y qué tan ___ está la persona para la tarea.","resp":["dispuesta","dispuesto"]},{"frase":"Al experto comprometido le corresponde ___.","resp":["delegar"]},{"frase":"Al nuevo sin experiencia le corresponde ___.","resp":["dirigir","ordenar"]}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el mismo trato para la nueva y para la experta</b><br>Rosa coordina a seis enfermeras en un hospital de Culiacán. Con todas usa el mismo estilo: les explica cada paso de cada procedimiento. Lucía, con 15 años de experiencia, se siente tratada como novata y está desmotivada. Karen, recién egresada, recibió la misma instrucción una vez y luego la dejaron sola en su primera guardia nocturna.<br>El estilo se elige por persona y por tarea. Sobredirigir desmotiva al experto; delegar al novato es abandonarlo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué estilo conviene con Lucía en procedimientos que domina?","ops":["Delegar","Persuadir","Dirigir paso a paso"],"correcta":0,"explica":"Es capaz y está dispuesta: necesita autonomía."},{"p":"¿Qué estilo conviene con Karen en su primera guardia?","ops":["Delegar","Dirigir y acompañar de cerca","Participar"],"correcta":1,"explica":"Aún no tiene la capacidad para esa tarea."},{"p":"El estilo situacional se elige…","ops":["por persona, para siempre","por persona y por tarea","según el humor del jefe"],"correcta":1,"explica":"La misma persona puede ser experta en una tarea y novata en otra."}]},{"tipo":"comparar","titulo":"Cómo se oye con cada una","mal":"«A ver, todas pongan atención, les explico paso a paso.»","bien":"«Lucía, te encargo el protocolo de curaciones; avísame si necesitas algo. Karen, esta semana hacemos juntas la primera guardia y el jueves la revisamos.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Elige a tres personas de un equipo que conozcas y, para una tarea concreta, decide qué tan capaz y qué tan dispuesta está cada una, y qué estilo usarías.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe un error que hayas visto (o cometido) por sobredirigir o por delegar de más, y qué habrías hecho distinto.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Mapa situacional del equipo","texto":"MAPA SITUACIONAL — [Tarea]\nPersona | Capacidad (baja/media/alta) | Disposición (baja/media/alta) | Estilo | Qué haré esta semana\n[ ] | [ ] | [ ] | [Dirigir / Persuadir / Participar / Delegar] | [ ]\n\nRegla: baja capacidad → dirigir; algo de capacidad, poca confianza → persuadir o participar; alta capacidad y disposición → delegar.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["El estilo se elige por persona y por tarea, no por gusto del jefe.","Dirigir → persuadir → participar → delegar, conforme crece la capacidad y la disposición.","Sobredirigir desmotiva al experto; delegar al novato es abandonarlo."]}],"d-liderazgo-m1-l4":[{"tipo":"texto","texto":"Casi todos los jefes nuevos cometen los mismos errores. No es falta de talento: es que nadie te enseñó el puesto. Conocerlos de antemano te ahorra meses de desgaste."},{"tipo":"tabla","titulo":"Errores frecuentes","encabezados":["Error","Por qué pasa","Qué hacer en su lugar"],"filas":[["Seguir haciendo el trabajo operativo","Es tu zona de confort y das resultados rápidos","Enseña una vez, delega y revisa"],["Querer caerle bien a todos","Miedo a perder a tus amigos","Sé cercano, pero aplica las mismas reglas a todos"],["Llegar a cambiarlo todo","Quieres demostrar que mereces el puesto","Primero escucha y entiende; cambia poco y bien"],["Favorecer a tus antiguos compañeros","Confianza y lealtad previa","Criterios claros y públicos para turnos, permisos y horas extra"],["No pedir ayuda a tu jefe","Crees que se verá como debilidad","Pide orientación con propuestas: «esto pienso hacer, ¿qué me recomiendas?»"],["Evitar las conversaciones difíciles","Incomodidad","Hablar pronto, en privado y con hechos (lo verás en el módulo 2)"]]},{"tipo":"comparar","titulo":"Tu primera junta con el equipo","malTitulo":"Así no","mal":"«A partir de hoy las cosas van a cambiar. Ya no soy su compañero, soy su jefe, y aquí se acabó el relajo.»","bienTitulo":"Así sí","bien":"«Muchos me conocen como compañero y eso no cambia el respeto que les tengo. Mi trabajo ahora es que tengamos lo necesario para cumplir y que nos vaya bien a todos. En las próximas dos semanas voy a platicar con cada uno para escuchar qué funciona y qué no.»"},{"tipo":"texto","texto":"Ejemplo: Daniela fue ascendida a coordinadora de un call center de cobranza en Guadalajara. Su mejor amiga, Paty, sigue como agente. Paty empezó a llegar tarde «porque Dani entiende». Daniela habló con ella en privado: «Te aprecio igual que siempre. Justo por eso te lo digo a ti primero: las reglas de puntualidad aplican para todos, incluyéndote. Si hay algo que te complica llegar, platiquémoslo»."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu antiguo compañero te pide el mejor turno «por los viejos tiempos». Lo correcto es…","ops":["Negárselo sin explicación","Aplicar el mismo criterio que a los demás y explicarlo","Dárselo para no perder la amistad"],"correcta":1,"explica":"La justicia visible es la base de tu credibilidad."},{"p":"En tu primera semana conviene…","ops":["Escuchar a cada persona y entender el trabajo antes de cambiar cosas","Cambiar todos los procesos","Encerrarte en la oficina"],"correcta":0},{"p":"Pedir ayuda a tu jefe es…","ops":["Señal de debilidad","Innecesario si eres bueno","Recomendable, llevando una propuesta"],"correcta":2}]},{"tipo":"ordenar","rotulo":"Ordena la frase","items":[{"frase":"Cercano con todos pero las mismas reglas para todos","es":"La regla de oro con tus excompañeros"}]},{"tipo":"reflexion","rotulo":"Tu error más probable","pregunta":"¿Cuál de estos errores crees que te costará más trabajo evitar y por qué? Escribe una acción concreta para esta semana.","ayuda":"El error que más me cuesta es… porque… Esta semana voy a…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el jefe que cambió todo en la primera semana</b><br>Iván llegó como jefe de almacén a una cadena de supermercados en Toluca. En su primera semana cambió los turnos, el acomodo de los pasillos y el formato de inventario. Además, invitó a comer solo a los dos que ya conocía de antes. El equipo empezó a decir que tenía «consentidos» y que «no sabía cómo funcionaban las cosas aquí».<br>Primero escucha y entiende; cambia poco y bien. Cercanía sí, favoritismo no: mismas reglas para todos."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué debió hacer Iván en su primer mes?","ops":["Cambiar todo rápido para marcar su estilo","Escuchar al equipo, entender cómo funciona el almacén y elegir uno o dos cambios","No cambiar nada nunca"],"correcta":1,"explica":"Cambiar sin entender genera resistencia y errores."},{"p":"Invitar a comer solo a sus conocidos provoca…","ops":["un mejor equipo","percepción de favoritismo","nada"],"correcta":1,"explica":"Las mismas reglas y atenciones para todos."},{"p":"¿Qué es un error común del jefe nuevo con sus excompañeros?","ops":["Pedirles su opinión","Querer seguir siendo «uno más» y no marcar los acuerdos","Saludarlos"],"correcta":1,"explica":"La relación cambia y hay que hablarlo."}]},{"tipo":"comparar","titulo":"Cómo se oye con un excompañero","mal":"«Tranquilo, conmigo no cambia nada, somos cuates.»","bien":"«Seguimos siendo amigos, y ahora me toca revisar que todos cumplan, tú incluido. Si algo no te parece, prefiero que me lo digas a mí primero.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe los cinco errores de jefe nuevo que más has visto y una alternativa práctica para cada uno.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Si hoy te nombraran jefe de tus compañeros, escribe lo que les dirías en la primera junta y lo que harías en tu primer mes.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Mis primeros 30 días como jefe","texto":"PRIMEROS 30 DÍAS\nSemana 1: platicar 15 minutos con cada persona: ¿qué funciona?, ¿qué estorba?, ¿qué esperas de mí?\nSemana 2: entender procesos, indicadores y problemas repetidos.\nSemana 3: acordar con mi jefe expectativas y prioridades.\nSemana 4: elegir 1 o 2 cambios, explicarlos y empezar.\nReglas que aplicaré a todos por igual: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Los errores del jefe nuevo son comunes y previsibles.","Primero escucha y entiende; cambia poco y bien.","Cercanía sí, favoritismo no: mismas reglas para todos."]}],"d-liderazgo-m1-lab":[{"tipo":"destacado","texto":"Te acaban de nombrar supervisora de cajas en <b>Supermercados La Económica</b>, en Toluca. Coordinas a 9 cajeros; hasta la semana pasada eras una de ellos. Tu mejor amiga, Brenda, está en el equipo. Don Chuy, con 20 años en la tienda, esperaba el puesto."},{"tipo":"texto","texto":"<p><b>Escena 1 — La primera junta.</b> Todos te miran esperando qué vas a decir.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe lo que dirías en tu primera junta de 10 minutos.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — Brenda.</b> Te pide que le des los mejores turnos «como amigas».</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe cómo le respondes sin perder la amistad ni la justicia.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — Don Chuy.</b> Está molesto y hace comentarios frente a los demás.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe cómo abordarías a don Chuy y qué estilo usarías con él.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — El mapa.</b> Hay dos cajeros nuevos, cinco con experiencia y uno con muchos errores.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe qué estilo usarías con cada grupo y por qué.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"Con Brenda, lo correcto es…","ops":["aplicar las mismas reglas que a todos y hablarlo con claridad","darle los mejores turnos en secreto","dejar de hablarle"],"correcta":0,"explica":"Cercanía sí, favoritismo no."},{"p":"Con don Chuy, conviene…","ops":["ignorarlo","hablar en privado, reconocer su experiencia e invitarlo a aportar","exhibirlo frente al equipo"],"correcta":1,"explica":"Su experiencia puede ser un apoyo."},{"p":"Con los cajeros nuevos, el estilo adecuado es…","ops":["participar","delegar","dirigir y acompañar de cerca"],"correcta":2,"explica":"Aún no dominan la tarea."}]},{"tipo":"plantilla","rotulo":"Diagnóstico del equipo","texto":"DIAGNÓSTICO — [Equipo]\nPersona | Fortalezas | Áreas de mejora | Capacidad | Disposición | Estilo\n\nRelaciones delicadas: [ ]\nAcuerdos de la primera junta: [ ]","nota":"Cópiala y úsala en tu trabajo."}],"d-liderazgo-m2-l1":[{"tipo":"texto","texto":"La mayoría de los problemas en un turno no vienen de que la gente no quiera trabajar, sino de que <b>no entendió lo mismo</b> que tú. Dos herramientas resuelven buena parte de eso: la <b>junta corta de arranque</b> y la <b>instrucción clara</b>."},{"tipo":"pasos","rotulo":"Junta de arranque de turno (10 minutos, de pie)","pasos":["<b>Seguridad (1 min):</b> un riesgo del día o un recordatorio concreto.","<b>Resultados de ayer (2 min):</b> una o dos cifras: piezas, llamadas atendidas, tiempo de espera, faltantes.","<b>Meta y prioridades de hoy (3 min):</b> qué es lo más importante y quién hace qué.","<b>Problemas y apoyos (3 min):</b> qué nos puede atorar; lo que no se resuelve en un minuto se platica después con quien corresponda.","<b>Cierre (1 min):</b> repite la prioridad y reconoce algo que salió bien."]},{"tipo":"comparar","titulo":"Instrucción mala vs buena","malTitulo":"Mala","mal":"«Oigan, a ver si le echan ganas con lo del inventario, que está medio atrasado, ¿eh?»","bienTitulo":"Buena","bien":"«Pedro y Lupita: hoy terminan el conteo del pasillo 7, de abarrotes, antes de las 2 de la tarde. Usen la hoja de conteo nueva. Si encuentran diferencias de más de 5 piezas, me avisan por radio. Pedro, ¿me repites qué van a hacer?»"},{"tipo":"texto","texto":"Una instrucción clara responde: <b>quién</b>, <b>qué</b> exactamente, <b>para cuándo</b>, <b>con qué estándar</b> (cómo se ve bien hecho) y <b>qué hacer si hay un problema</b>. Y se cierra pidiendo que la persona la <b>repita con sus palabras</b>: no para humillarla, sino para comprobar que te explicaste bien."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"«Échenle ganas al inventario» es una mala instrucción porque…","ops":["Es grosera","No dice quién, qué, para cuándo ni con qué estándar","Es demasiado larga"],"correcta":1,"explica":"Suena amable, pero cada quien la entiende distinto."},{"p":"Pedir que te repitan la instrucción sirve para…","ops":["Verificar que te explicaste bien","Hacer quedar mal a la persona","Alargar la junta"],"correcta":0},{"p":"En la junta de arranque, un problema que requiere 20 minutos de discusión…","ops":["Se discute ahí con todos","Se ignora","Se platica después solo con los involucrados"],"correcta":2}]},{"tipo":"completar","rotulo":"Los elementos de una instrucción clara","items":[{"frase":"Quién, qué, para ___, con qué estándar y qué hacer si hay problema.","resp":["cuándo","cuando"]},{"frase":"Al final pide que la persona la ___ con sus palabras.","resp":["repita"]},{"frase":"La junta de arranque dura unos ___ minutos.","resp":["10","diez"]}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «ya saben lo que tienen que hacer»</b><br>El jefe de turno de una planta de alimentos en Irapuato hace su junta de arranque en 40 minutos, habla solo él y termina con «ya saben lo que tienen que hacer». Ese día pidió «limpiar la línea 2 temprano» y cada quien entendió algo distinto: unos a las 6, otros al terminar el primer lote. Se perdió una hora de producción.<br>Junta de arranque de 10 minutos. Instrucción clara: qué, para qué, cómo, cuándo y con qué estándar, y verifica que se entendió."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué le faltó a la instrucción?","ops":["Más palabras","Cuándo exactamente y con qué estándar","Tono más fuerte"],"correcta":1,"explica":"«Temprano» significa algo distinto para cada quien."},{"p":"¿Cómo verificas que se entendió?","ops":["Suponiéndolo","Preguntando «¿entendieron?»","Pidiendo que la persona lo repita con sus palabras"],"correcta":2,"explica":"A «¿entendieron?» casi todos dicen que sí."},{"p":"Una junta de arranque útil incluye…","ops":["regaños generales","resultado de ayer, meta de hoy, riesgos y quién hace qué","la historia de la empresa"],"correcta":1,"explica":"Corta y enfocada en el día."}]},{"tipo":"comparar","titulo":"Cómo se da la instrucción","mal":"«Limpien la línea 2 temprano, ya saben.»","bien":"«Pepe y Laura: limpieza completa de la línea 2 a las 6:00, antes del primer lote, con el checklist de sanidad. Pepe, ¿me repites qué vas a hacer y a qué hora?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Reescribe tres instrucciones vagas que hayas recibido o dado, para que digan qué, para qué, cómo, cuándo y con qué estándar.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe el guion de una junta de arranque de 10 minutos para un equipo que conozcas.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Junta de arranque de 10 minutos","texto":"JUNTA DE ARRANQUE — [Turno / Fecha]\n1. Cómo nos fue ayer (1 min): [dato]\n2. Meta de hoy (2 min): [ ]\n3. Seguridad o riesgo del día (2 min): [ ]\n4. Quién hace qué (3 min): [ ]\n5. Dudas y cierre (2 min)\n\nINSTRUCCIÓN CLARA: Qué · Para qué · Cómo · Cuándo · Estándar · ¿Me lo repites?","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Junta de arranque: seguridad, resultados, meta, problemas y cierre en 10 minutos.","Instrucción clara: quién, qué, cuándo, estándar y qué hacer si hay un problema.","Pide que te la repitan: así compruebas que te explicaste bien."]}],"d-liderazgo-m2-l2":[{"tipo":"texto","texto":"<b>Escuchar activamente</b> es poner atención completa para entender lo que la otra persona dice y siente, y demostrarle que la entendiste. No es quedarte callado esperando tu turno para contestar. Es una de las conductas que más confianza construye en un equipo."},{"tipo":"tabla","titulo":"Técnicas de escucha activa","encabezados":["Técnica","Ejemplo"],"filas":[["Atención completa","Guardas el celular, lo miras y dejas lo que estabas haciendo"],["Parafrasear","«Entonces, lo que me dices es que la báscula marca distinto desde el lunes…»"],["Preguntas abiertas","«¿Qué pasó exactamente?», «¿Qué has intentado?»"],["Reflejar la emoción","«Te veo frustrado con esto, y lo entiendo»"],["Resumir y acordar","«Quedamos en que reviso con mantenimiento y te aviso mañana a las 10»"]]},{"tipo":"practica","rotulo":"¿Escucha activa o no?","preguntas":[{"p":"Un cajero te cuenta un problema y tú contestas mensajes mientras dices «ajá, ajá».","ops":["Sí es escucha activa","Sí, mientras le contestes «ajá»","Es escucha activa parcial","No es escucha activa"],"correcta":3,"explica":"La atención dividida se nota y la persona deja de contarte cosas; escuchar activamente implica dejar lo demás y mirar a quien habla."},{"p":"Dices: «A ver si entendí: el cliente pidió cancelar y el sistema no te dejó, ¿correcto?»","ops":["Sí, es parafrasear","No, es dar un consejo","No, es emitir un juicio","No, es interrumpir"],"correcta":0,"explica":"Repetir con tus palabras lo que entendiste y pedir confirmación es parafrasear, una técnica central de la escucha activa."},{"p":"Antes de que termine, le dices «ya sé, ya sé, eso pasa siempre».","ops":["Es escucha activa resumida","No es escucha activa","Sí, demuestra experiencia","Sí, muestra empatía"],"correcta":1,"explica":"Interrumpir para decir que ya sabes invalida a la persona y te hace perder detalles; eso no es escucha activa aunque tengas experiencia."}]},{"tipo":"texto","texto":"<b>Comunicación hacia arriba.</b> Tu jefe tiene poco tiempo y muchos pendientes. Si llegas solo con quejas («todo está mal en el turno»), te volverás el que siempre se queja. Llega con <b>hechos, impacto y propuesta</b>. Y avisa de las malas noticias <b>temprano</b>: a nadie le gusta enterarse a las 5:55 de que el embarque de las 6 no sale."},{"tipo":"comparar","titulo":"Cómo le planteas un problema a tu jefe","malTitulo":"Así no","mal":"«Jefe, es que ya no se puede con el turno de noche, nadie quiere trabajar y la máquina 4 está de la fregada.»","bienTitulo":"Así sí","bien":"«Jefe, la máquina 4 tuvo 3 paros esta semana, 5 horas en total; perdimos unas 900 piezas. Mantenimiento dice que falta una refacción que tarda 10 días. Propongo pasar el modelo X a la máquina 6 mientras llega. Necesito su visto bueno para mover a dos operadores. ¿Lo autoriza?»"},{"tipo":"plantilla","rotulo":"Mensaje breve para tu jefe (hechos, impacto, propuesta)","texto":"Asunto: [Tema en pocas palabras]\n\nQué pasa: [hecho concreto con dato: cuánto, desde cuándo]\nImpacto: [en producción, clientes, costo, seguridad o personas]\nLo que ya hice: [acciones tomadas]\nPropuesta: [opción recomendada y, si hay, una alternativa]\nLo que necesito de usted: [decisión, recurso o apoyo] para [fecha u hora]","nota":"Úsalo por correo, WhatsApp de trabajo o como guion para una llamada de dos minutos."},{"tipo":"relacionar","rotulo":"Relaciona la frase con la técnica","pares":[["«¿Qué has intentado hasta ahora?»","Pregunta abierta"],["«O sea que el proveedor llegó dos horas tarde, ¿verdad?»","Parafrasear"],["«Se nota que esto te tiene preocupada»","Reflejar la emoción"],["«Propongo mover el modelo X a la máquina 6»","Propuesta para tu jefe"]]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el jefe que se enteraba al final</b><br>La coordinadora de un call center en Guadalajara escucha a su equipo con el celular en la mano, interrumpe para dar soluciones y termina las frases de los demás. Su equipo dejó de contarle los problemas. Además, a su gerente solo le llevaba quejas sin datos, y él dejó de tomarla en cuenta.<br>Escucha activa: atención completa, preguntar, parafrasear y no interrumpir. Hacia arriba: datos, opciones y una recomendación."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué es parafrasear?","ops":["Repetir con tus palabras lo que entendiste para confirmar","Dar tu opinión","Cambiar de tema"],"correcta":0,"explica":"Demuestra que escuchaste y evita malentendidos."},{"p":"¿Cómo llevar un problema a tu jefe?","ops":["Esperar a que él pregunte","Con datos, dos o tres opciones y tu recomendación","Solo la queja"],"correcta":1,"explica":"Tu jefe decide mejor con información."},{"p":"¿Por qué el equipo dejó de contarle problemas?","ops":["Porque tenían miedo al gerente","Porque no había problemas","Porque no se sentían escuchados"],"correcta":2,"explica":"Si no escuchas, la gente deja de hablar."}]},{"tipo":"comparar","titulo":"Cómo se lleva un problema al gerente","mal":"«La gente está muy estresada, esto ya no se aguanta.»","bien":"«El tiempo de espera subió de 2 a 6 minutos desde que se fueron dos agentes. Opciones: contratar a uno temporal o mover a dos de soporte en horas pico. Recomiendo la segunda por costo.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Practica escucha activa en una conversación de esta semana: escribe qué te dijeron, cómo lo parafraseaste y qué cambió en la plática.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cómo llevarías a tu jefe un problema real de tu trabajo con datos, opciones y recomendación.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Escucha activa y comunicación hacia arriba","texto":"ESCUCHA ACTIVA\n□ Celular guardado, mirada a la persona\n□ Preguntar: «¿Qué pasó? ¿Qué necesitas?»\n□ Parafrasear: «Entonces lo que me dices es…»\n□ No interrumpir ni dar la solución antes de entender\n\nHACIA ARRIBA\nSituación (con datos): [ ]\nOpciones: A [ ] · B [ ] · C [ ]\nMi recomendación y por qué: [ ]\nLo que necesito de ti: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Escucha activa: atención completa, parafrasear, preguntar, reflejar y acordar.","Con tu jefe: hechos, impacto y propuesta, no solo quejas.","Las malas noticias se avisan temprano."]}],"d-liderazgo-m2-l3":[{"tipo":"texto","texto":"La retroalimentación es información sobre cómo alguien está haciendo su trabajo para que <b>repita lo que funciona y corrija lo que no</b>. El problema es que solemos darla vaga («buen trabajo», «ponte las pilas») o atacando a la persona («eres un desordenado»). El modelo <b>SBI</b> (Situación, Comportamiento, Impacto; en inglés <i>Situation-Behavior-Impact</i>), difundido por el <b>Center for Creative Leadership</b>, te ayuda a ser concreto y justo."},{"tipo":"tabla","titulo":"Las tres partes del SBI","encabezados":["Parte","Qué dices","Ejemplo"],"filas":[["Situación","Cuándo y dónde pasó","«Ayer en el cierre de caja de las 3…»"],["Comportamiento","Lo que la persona hizo o dijo, observable, sin juicios","«…entregaste el arqueo con un faltante de $400 sin reportarlo en la bitácora…»"],["Impacto","El efecto que tuvo en el equipo, el cliente o el resultado","«…y el turno de la tarde tuvo que rehacer el conteo; salimos 40 minutos tarde.»"]],"nota":"Después del impacto, pregunta y acuerden: «¿Qué pasó?» y «¿Qué vas a hacer la próxima vez?»."},{"tipo":"comparar","titulo":"Retroalimentación mala vs buena","malTitulo":"Mala","mal":"«Otra vez tú con tus descuidos. Es que no pones atención, así no se puede.»","bienTitulo":"Buena (SBI)","bien":"«Hoy en el arranque de las 7 (S), la línea 2 empezó sin la revisión de guardas de seguridad (C). Eso nos expone a un accidente y a una multa en una auditoría (I). ¿Qué pasó? ¿Cómo aseguramos que se haga todos los días?»"},{"tipo":"comparar","titulo":"También para reconocer","malTitulo":"Vago","mal":"«Buen trabajo, sigue así.»","bienTitulo":"Concreto (SBI)","bien":"«En la llamada de las 11 con el cliente que quería cancelar (S), lo escuchaste sin interrumpir y le ofreciste el plan de pagos (C). Se quedó con nosotros y además te dio calificación de 5 (I). Así es como queremos atender.»"},{"tipo":"ordenar","rotulo":"Ordena el modelo","items":[{"frase":"Situación comportamiento e impacto","es":"Las tres partes del SBI en orden"}]},{"tipo":"practica","rotulo":"¿Qué parte del SBI es?","preguntas":[{"p":"«…el martes en la junta con calidad…»","ops":["Impacto","Situación","Comportamiento"],"correcta":1},{"p":"«…interrumpiste tres veces a la ingeniera cuando explicaba…»","ops":["Comportamiento","Situación","Impacto"],"correcta":0,"explica":"Es observable: cualquiera que estuvo ahí lo vio igual."},{"p":"«Eres muy grosero» ¿es un comportamiento?","ops":["Sí, es un hecho observable","No, es un juicio sobre la persona","Sí, es retroalimentación específica","Sí, es un comportamiento"],"correcta":1,"explica":"Es un juicio sobre la persona. Un comportamiento describe lo que hizo: «Le contestaste al cliente sin saludarlo»."},{"p":"«…y la ingeniera ya no quiso compartir los datos del lote.»","ops":["Comportamiento","Impacto","Situación"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Guion de retroalimentación SBI","texto":"RETROALIMENTACIÓN SBI\n\nPersona: [nombre]      Fecha: [__/__/____]      Tipo: [reconocimiento / mejora]\n\nSituación (cuándo y dónde): [...]\nComportamiento (lo que hizo o dijo, observable): [...]\nImpacto (efecto en el cliente, el equipo o el resultado): [...]\n\nPregunta abierta: ¿Cómo lo ves tú? / ¿Qué pasó?\nAcuerdo: [qué va a hacer, desde cuándo]\nSeguimiento: [fecha en que lo revisamos]","nota":"Da la retroalimentación de mejora en privado y pronto; el reconocimiento puede ser en público si a la persona no le incomoda."},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «échale más ganas»</b><br>Un supervisor de una tienda departamental en Monterrey le dijo a un vendedor: «Échale más ganas, te veo muy apagado». El vendedor no supo qué cambiar y se sintió juzgado. A otra vendedora que hizo una venta muy buena solo le dijo «bien». Ninguno de los dos cambió nada.<br>Modelo SBI: Situación, Comportamiento (Behavior) e Impacto. Sirve para reconocer y para corregir, con hechos, no con juicios."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué falla en «échale más ganas»?","ops":["Es un juicio vago, sin situación ni comportamiento concreto","Es muy directo","Es muy largo"],"correcta":0,"explica":"La persona no sabe qué cambiar."},{"p":"Una retroalimentación SBI de mejora sería…","ops":["«Eres muy flojo»","«Hoy en la mañana, con la clienta del abrigo, no le ofreciste probárselo, y se fue sin comprar»","«Tienes que mejorar tu actitud»"],"correcta":1,"explica":"Situación, comportamiento observable e impacto."},{"p":"Para reconocer a la vendedora, ¿qué agregarías a «bien»?","ops":["Nada, «bien» basta","Qué hizo exactamente y qué impacto tuvo","Un regalo"],"correcta":1,"explica":"El reconocimiento concreto enseña qué repetir."}]},{"tipo":"comparar","titulo":"Cómo se reconoce","mal":"«Bien.»","bien":"«Ayer, con el señor que buscaba traje (S), le preguntaste para qué evento era y le armaste el conjunto completo (B). Vendiste $12,000 y se fue contento (I). Eso es exactamente lo que quiero ver.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe dos retroalimentaciones SBI de reconocimiento y dos de mejora para personas reales o imaginarias de un equipo.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cómo respondería una persona a tu retroalimentación de mejora y cómo cerrarías la conversación con un acuerdo.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Retroalimentación SBI","texto":"RETROALIMENTACIÓN SBI\nSituación: cuándo y dónde, concreto: [ ]\nComportamiento: lo que hizo o dijo, observable: [ ]\nImpacto: qué causó en el cliente, el equipo o el resultado: [ ]\n\nSi es de mejora:\nPregunta: «¿Cómo lo ves tú?» [ ]\nAcuerdo: «¿Qué harás distinto la próxima vez?» [ ]\nSeguimiento: [fecha]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["SBI: Situación, Comportamiento observable e Impacto.","Habla de conductas, no de la persona.","Úsalo también para reconocer, y cierra con pregunta y acuerdo."]}],"d-liderazgo-m2-l4":[{"tipo":"texto","texto":"Una conversación difícil es aquella en la que <b>hay mucho en juego, opiniones distintas y emociones fuertes</b>: hablar del olor corporal de alguien, de llegadas tarde repetidas, de una queja de un cliente, de negar un permiso o de un rumor que está dañando al equipo. Evitarlas no las desaparece: las hace crecer."},{"tipo":"pasos","rotulo":"Cómo prepararla y conducirla","pasos":["<b>Prepárate:</b> reúne hechos (fechas, datos, ejemplos), define qué resultado quieres y piensa cómo puede reaccionar la persona.","<b>Elige lugar y momento:</b> en privado, sin prisa y no en caliente. Nunca frente al equipo ni por grupo de WhatsApp.","<b>Ve al grano con respeto:</b> «Quiero platicar contigo de algo importante: tus llegadas tarde».","<b>Describe con SBI</b> y luego <b>escucha</b> su versión sin interrumpir.","<b>Maneja la emoción:</b> si se enoja o llora, da un momento. «Entiendo que es incómodo. ¿Seguimos o prefieres que lo retomemos en 15 minutos?»","<b>Acuerden</b> algo concreto y una fecha de seguimiento. Si aplica, deja nota por escrito según el procedimiento de tu empresa."]},{"tipo":"comparar","titulo":"Frases que complican vs frases que ayudan","malTitulo":"Complican","mal":"«Siempre llegas tarde.» «Todos se quejan de ti.» «Tú sabrás, pero te va a ir mal.»","bienTitulo":"Ayudan","bien":"«Esta quincena llegaste tarde 4 veces: lunes 3, miércoles 5…» «Recibí dos comentarios sobre…» «Quiero que te vaya bien aquí; por eso lo platico contigo.»"},{"tipo":"practica","rotulo":"Caso: Martín, jefe de turno en un hospital de Aguascalientes","preguntas":[{"p":"Varios camilleros comentan que Toño no se baña y hay quejas de pacientes. Martín debería…","ops":["Hablar con Toño en privado, con respeto y hechos","Hacer una broma en la junta para que capte","Pedirle a otro compañero que se lo diga"],"correcta":0,"explica":"Un tema personal se trata en privado y directamente."},{"p":"Toño se pone rojo y se queda callado. Martín…","ops":["Sigue hablando rápido para terminar","Se ríe para romper la tensión","Le da un momento y reconoce que es incómodo"],"correcta":2},{"p":"Toño comenta que se descompuso el calentador de su casa. Martín…","ops":["Lo reporta a RH de inmediato como falta","Escucha y busca con él una solución (por ejemplo, usar las regaderas del hospital si la política lo permite)","Le dice que no es su problema"],"correcta":1,"explica":"Escuchar descubre causas que no imaginabas."}]},{"tipo":"reflexion","rotulo":"Tu conversación pendiente","pregunta":"¿Qué conversación difícil llevas tiempo posponiendo? Escribe los hechos concretos (sin juicios) y la primera frase con la que la vas a abrir.","ayuda":"Hechos: … Primera frase: «Quiero platicar contigo de…»"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la plática que se pospuso tres meses</b><br>La jefa de cocina de un restaurante en Oaxaca notaba que un cocinero llegaba 20 minutos tarde casi a diario. No le decía nada «para no hacer drama». Los demás empezaron a llegar tarde también. Cuando por fin habló, estaba tan molesta que gritó delante de todos.<br>Las conversaciones difíciles se preparan: en privado, pronto, con hechos, escuchando y cerrando con un acuerdo y seguimiento."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué error cometió la jefa?","ops":["Contar los retrasos","Posponer la conversación y luego tenerla enojada y en público","Hablar con el cocinero"],"correcta":1,"explica":"Posponer hace crecer el problema y la emoción."},{"p":"¿Dónde y cómo se tiene esta conversación?","ops":["Frente al equipo para que sirva de ejemplo","En privado, pronto y con hechos","Por WhatsApp"],"correcta":1,"explica":"La privacidad protege la dignidad y facilita el acuerdo."},{"p":"Después de describir los hechos, conviene…","ops":["anunciar la sanción","cambiar de tema","preguntar qué está pasando y escuchar"],"correcta":2,"explica":"Puede haber una causa que no conoces."}]},{"tipo":"comparar","titulo":"Cómo se abre la conversación","mal":"«¡Ya estoy harta de que siempre llegues tarde!» (frente a todos)","bien":"«Juan, ¿tienes 10 minutos? Quiero platicar contigo. En las últimas tres semanas llegaste después de las 7:20 en 11 días. ¿Qué está pasando?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Prepara por escrito una conversación difícil que tengas pendiente (o una imaginaria): hechos, cómo abrirás, qué preguntarás y qué acuerdo buscas.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cómo responderías si la persona se enoja o se pone a llorar durante la conversación.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Guion de conversación difícil","texto":"CONVERSACIÓN DIFÍCIL — [Persona]\nLugar y momento (privado, pronto): [ ]\nHechos (fechas, datos): [ ]\nApertura: «[Nombre], quiero platicar contigo sobre…»\nPregunta: «¿Qué está pasando?»\nEscuchar y parafrasear: [ ]\nLo que necesito: [ ]\nAcuerdo: [qué, desde cuándo]\nSeguimiento: [fecha]\nSi hay emoción fuerte: pausa, reconocer la emoción, ofrecer retomar.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Evitar una conversación difícil la hace crecer.","Prepárala con hechos, en privado y sin prisa; escucha su versión.","Termina con un acuerdo concreto y fecha de seguimiento."]}],"d-liderazgo-m2-lab":[{"tipo":"destacado","texto":"Eres jefe de turno en <b>Empacadora del Valle</b>, en Zamora. Esta semana llega un pedido urgente de exportación, un empacador nuevo comete muchos errores, una empacadora con experiencia sacó el mejor récord del mes y un operador lleva tres semanas llegando tarde."},{"tipo":"texto","texto":"<p><b>Escena 1 — El pedido urgente.</b> Debes explicar al equipo cómo empacar para exportación.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe la instrucción clara con qué, para qué, cómo, cuándo y estándar.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — El récord.</b> La empacadora con experiencia empacó 1,200 cajas sin errores.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe la retroalimentación SBI de reconocimiento.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — El empacador nuevo.</b> Etiqueta mal una de cada diez cajas.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe la retroalimentación SBI de mejora y el acuerdo.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — Los retrasos.</b> El operador llegó tarde 12 de los últimos 15 días.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe cómo abrirías y cerrarías la conversación difícil.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"«Empaquen bien que es para exportación» es…","ops":["una instrucción clara","una instrucción vaga","retroalimentación SBI"],"correcta":1,"explica":"Falta cómo, cuándo y con qué estándar."},{"p":"La retroalimentación al nuevo debe ser…","ops":["pronto, en privado y con hechos","frente al equipo","al final del mes"],"correcta":0,"explica":"Así puede corregir a tiempo."},{"p":"La conversación con el operador termina con…","ops":["nada","una amenaza","un acuerdo concreto y fecha de seguimiento"],"correcta":2,"explica":"Sin acuerdo, no hay cambio."}]},{"tipo":"plantilla","rotulo":"Semana de comunicación","texto":"SEMANA — [Equipo]\nInstrucciones clave dadas: [ ]\nReconocimientos SBI: [ ]\nRetroalimentaciones de mejora: [ ]\nConversaciones difíciles y acuerdos: [ ]\nSeguimientos pendientes: [ ]","nota":"Cópiala y úsala en tu trabajo."}],"d-liderazgo-m3-l1":[{"tipo":"texto","texto":"«Mejorar la atención», «bajar la merma», «echarle más ganas»: así llegan muchas metas. Tu trabajo es convertirlas en algo que tu equipo pueda <b>entender, medir y lograr</b>. La herramienta más usada es el criterio <b>SMART</b>, que George T. Doran publicó en 1981. Hoy se usa sobre todo en esta versión:"},{"tipo":"tabla","titulo":"Qué significa SMART","encabezados":["Letra","Significado","Pregunta de control"],"filas":[["S","Específico","¿Queda claro qué se va a lograr y quién?"],["M","Medible","¿Con qué número sabremos si se logró?"],["A","Alcanzable","¿Es posible con la gente y los recursos que tenemos?"],["R","Relevante","¿Ayuda a la meta del área o de la empresa?"],["T","Con tiempo definido","¿Para cuándo?"]],"nota":"Hay variantes (por ejemplo, la «A» como «asignable»); lo importante es que el objetivo pase las cinco preguntas."},{"tipo":"comparar","titulo":"Objetivo vago vs objetivo SMART","malTitulo":"Vago","mal":"«Hay que bajar las filas en cajas.»","bienTitulo":"SMART","bien":"«Del 1 al 31 de octubre, en la sucursal Centro, reducir el tiempo promedio de espera en cajas de 12 a 8 minutos en horario de 12 a 3, abriendo una caja adicional y midiendo con el turnero.»"},{"tipo":"practica","rotulo":"¿Es SMART?","preguntas":[{"p":"«Mejorar la calidad este año.»","ops":["Sí, es SMART","Casi: solo le falta la fecha","No: no es específico ni medible","Sí: «este año» la vuelve medible"],"correcta":2,"explica":"No dice qué calidad, cuánto mejorar ni cómo se mide; tener plazo no basta para que sea SMART."},{"p":"«Bajar el rechazo de la línea 3 de 2.5% a 1.5% al cierre de diciembre.»","ops":["No, le falta todo","Sí: es específico, medible y con fecha","No: no dice cómo se va a lograr","No: le falta nombrar al responsable"],"correcta":1,"explica":"Dice qué (rechazo de la línea 3), cuánto (de 2.5% a 1.5%) y cuándo (cierre de diciembre): es específico, medible y con fecha."},{"p":"«Atender 500 llamadas por hora por agente a partir de mañana.»","ops":["Falla en alcanzable","Falla en medible","Es perfectamente SMART","Falla en el plazo"],"correcta":0,"explica":"Es medible y tiene fecha, pero 500 llamadas por hora es imposible; un objetivo inalcanzable desmotiva porque nadie lo intenta en serio."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La «M» de SMART significa ___.","resp":["medible"]},{"frase":"La «T» pide un ___ definido.","resp":["tiempo","plazo"]},{"frase":"Un objetivo imposible falla en ser ___.","resp":["alcanzable"]}]},{"tipo":"reflexion","rotulo":"Convierte tu meta","pregunta":"Toma una meta vaga que te hayan dado y reescríbela como objetivo SMART para tu equipo.","ayuda":"Del ___ al ___, [equipo] va a lograr [resultado medible] pasando de ___ a ___, mediante…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «vender más este mes»</b><br>El gerente de una sucursal bancaria en León le puso a su equipo la meta «vender más tarjetas este mes». A mitad de mes nadie sabía si iban bien o mal. Otro gerente, en la sucursal vecina, puso «colocar 40 tarjetas de crédito del 1 al 30 de junio, 8 por ejecutivo», y revisaba el avance cada lunes.<br>SMART: específico, medible, alcanzable, relevante y con tiempo. Sin número y sin fecha no hay objetivo, hay deseo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué le falta a «vender más tarjetas este mes»?","ops":["Una fecha","Un número concreto y cómo se medirá","Un tono motivador"],"correcta":1,"explica":"«Más» no se puede verificar."},{"p":"Si el año pasado colocaron 20 tarjetas al mes, una meta de 200 sería…","ops":["demasiado fácil","poco alcanzable y desmotivaría","SMART"],"correcta":1,"explica":"Un objetivo imposible desmotiva tanto como uno vago."},{"p":"¿Por qué revisar cada lunes?","ops":["No hace falta","Para regañar","Para corregir a tiempo durante el mes"],"correcta":2,"explica":"El seguimiento convierte la meta en acción."}]},{"tipo":"comparar","titulo":"Cómo se escribe la meta","mal":"«Vender más tarjetas este mes.»","bien":"«Colocar 40 tarjetas de crédito del 1 al 30 de junio (8 por ejecutivo). Revisión cada lunes a las 9.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Convierte tres metas vagas de un equipo que conozcas en objetivos SMART.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Para uno de esos objetivos, escribe cómo lo repartirías entre las personas del equipo y cómo darías seguimiento semanal.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Objetivo SMART del equipo","texto":"OBJETIVO SMART\nEspecífico (qué exactamente): [ ]\nMedible (número): [ ]\nAlcanzable (comparado con el histórico): [ ]\nRelevante (a qué resultado del negocio aporta): [ ]\nTiempo (fecha límite): [ ]\n\nObjetivo final: [ ]\nReparto por persona: [ ]\nRevisión: [día y hora]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["SMART: específico, medible, alcanzable, relevante y con tiempo.","Sin número y sin fecha no hay objetivo, hay deseo.","Un objetivo imposible desmotiva tanto como uno vago."]}],"d-liderazgo-m3-l2":[{"tipo":"texto","texto":"Delegar no es «aventar» trabajo. Es <b>encargar un resultado</b> a alguien, darle la autoridad y los recursos para lograrlo, y dar seguimiento. Tú sigues siendo responsable ante tu jefe. Un error común es delegar sin aclarar <b>cuánta libertad</b> tiene la persona para decidir."},{"tipo":"tabla","titulo":"Niveles de delegación","encabezados":["Nivel","Qué le dices","Ejemplo"],"filas":[["1. Investiga","«Averigua y me informas; yo decido»","Cotizar tres proveedores de guantes"],["2. Recomienda","«Investiga y dime qué recomiendas»","Proponer el rol de vacaciones del área"],["3. Decide y avísame antes","«Decide, pero avísame antes de actuar»","Reacomodar al personal cuando falta alguien"],["4. Actúa y avísame después","«Resuélvelo y me cuentas cómo quedó»","Atender quejas menores de clientes"],["5. Actúa","«Es tuyo; no necesitas avisarme»","Ordenar el acomodo del almacén de empaque"]],"nota":"Sube de nivel a la persona conforme demuestra capacidad (recuerda el liderazgo situacional del módulo 1)."},{"tipo":"pasos","rotulo":"Cómo delegar bien","pasos":["Elige la tarea y a la persona (capacidad y disposición).","Explica el <b>resultado esperado</b>, el porqué y la fecha.","Aclara el <b>nivel de delegación</b> y los recursos con que cuenta.","Acuerda <b>puntos de revisión</b> (no esperes al final para ver cómo va).","Reconoce el resultado y aprende de lo que salió mal, sin quitarle la tarea al primer error."]},{"tipo":"tabla","titulo":"Matriz de Eisenhower","encabezados":["","Urgente","No urgente"],"filas":[["Importante","<b>Hazlo ya:</b> máquina parada, cliente molesto, accidente","<b>Agéndalo:</b> capacitar, planear, juntas 1 a 1, mantenimiento preventivo"],["No importante","<b>Delégalo:</b> muchas llamadas, reportes de rutina, trámites","<b>Elimínalo:</b> chats sin fin, juntas sin objetivo"]],"nota":"Se atribuye al presidente Dwight D. Eisenhower y la popularizó Stephen Covey. El cuadrante que más descuidan los jefes nuevos es el de «importante no urgente»."},{"tipo":"relacionar","rotulo":"¿En qué cuadrante va?","pares":[["Se cayó el sistema de cobro en cajas a la hora pico","Hazlo ya"],["Diseñar la capacitación del nuevo auxiliar","Agéndalo"],["Capturar el reporte diario de asistencia","Delégalo"],["Ver memes en el grupo del turno","Elimínalo"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Delegas una tarea a Rosa y ella comete un error pequeño. Lo mejor es…","ops":["Revisar juntos qué pasó y dejar que siga con la tarea","Quitarle la tarea y hacerla tú","Regañarla frente a todos"],"correcta":0,"explica":"Si le quitas la tarea al primer error, nadie querrá asumir responsabilidades."},{"p":"Si dices «resuélvelo y me cuentas cómo quedó», estás en el nivel…","ops":["Investiga","Recomienda","Actúa y avísame después"],"correcta":2},{"p":"Las juntas 1 a 1 con tu equipo son…","ops":["Algo que se puede eliminar","Importantes no urgentes: hay que agendarlas","Urgentes no importantes"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «encárgate del inventario»</b><br>La jefa de una farmacia en Hermosillo le dijo a su auxiliar: «Encárgate del inventario». La auxiliar pensó que solo tenía que contar. Cuando encontró medicamentos caducados, no supo si podía sacarlos de venta o tenía que preguntar. Esperó a la jefa, que estaba de vacaciones, y un cliente se llevó un producto caducado.<br>Delegar es encargar un resultado con autoridad, recursos y seguimiento. Aclara el nivel: investiga, recomienda, decide y avisa, actúa y avisa, o actúa."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué faltó al delegar?","ops":["Aclarar el nivel de autoridad y el resultado esperado","Un bono","Más tiempo"],"correcta":0,"explica":"La auxiliar no sabía qué podía decidir."},{"p":"¿Qué nivel convenía para sacar caducados de venta?","ops":["Investiga y reporta","Recomienda y espera","Actúa y avisa"],"correcta":2,"explica":"Es urgente y la regla es clara."},{"p":"En la matriz de Eisenhower, el inventario mensual es…","ops":["ni urgente ni importante","urgente y no importante","importante no urgente: agendarlo o delegarlo con fecha"],"correcta":2,"explica":"Si no se agenda, se vuelve urgente."}]},{"tipo":"comparar","titulo":"Cómo se delega","mal":"«Encárgate del inventario.»","bien":"«Te encargo el inventario mensual: contar, comparar con el sistema y sacar de venta lo caducado. Lo caducado lo retiras tú y me avisas. Lo demás me lo presentas el viernes.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Elige tres tareas que podrías delegar (o que delega un jefe que conozcas) y escribe para cada una: a quién, qué resultado, qué nivel de autoridad y cuándo revisarás.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Ordena tus pendientes de esta semana en la matriz de Eisenhower y escribe qué vas a delegar o eliminar.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Hoja de delegación","texto":"DELEGACIÓN\nTarea: [ ]\nA quién: [ ]\nResultado esperado: [ ]\nNivel: □ Investiga y reporta □ Recomienda □ Decide y avisa □ Actúa y avisa □ Actúa\nRecursos y accesos: [ ]\nFecha de entrega: [ ]  Revisiones: [ ]\n\nEISENHOWER: Hacer ya · Agendar · Delegar · Eliminar","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Delegar es encargar un resultado con autoridad, recursos y seguimiento.","Aclara el nivel: investiga, recomienda, decide y avisa, actúa y avisa, actúa.","Eisenhower: hazlo, agéndalo, delégalo o elimínalo; protege lo importante no urgente."]}],"d-liderazgo-m3-l3":[{"tipo":"texto","texto":"Lo que no se mide se discute con opiniones. Con unos cuantos <b>indicadores</b> puedes ver quién necesita apoyo, reconocer con justicia y hablar con tu jefe con datos. Para un equipo operativo, casi siempre bastan tres: <b>cumplimiento de meta</b>, <b>calidad</b> y <b>asistencia</b>. Aquí trabajarás con los de un turno de ensamble en una planta de Celaya."},{"tipo":"excel","rotulo":"Cumplimiento por operador y semáforo","datos":[["Operador","Meta (piezas)","Piezas buenas","% cumplimiento","Semáforo"],["Andrea",1200,1260,"",""],["Brenda",1200,1116,"",""],["Carlos",1200,1008,"",""],["Diego",1000,1000,"",""],["Elena",1000,870,"",""],["Fernando",1000,1050,"",""]],"retos":[{"celda":"D2","formula":"=C2/B2","esperado":1.05,"texto":"<b>D2</b>: calcula el % de cumplimiento de Andrea: piezas buenas entre meta.","pista":"=C2/B2. En Excel puedes darle formato de porcentaje: 1.05 es 105%."},{"celda":"D3","formula":"=C3/B3","esperado":0.93,"texto":"<b>D3</b>: cumplimiento de Brenda."},{"celda":"D4","formula":"=REDONDEAR(C4/B4,2)","esperado":0.84,"requiere":"REDONDEAR(","texto":"<b>D4</b>: cumplimiento de Carlos redondeado a 2 decimales con REDONDEAR."},{"celda":"E2","formula":"=SI(D2>=1,\"Verde\",SI(D2>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Verde","requiere":"SI(","texto":"<b>E2</b>: semáforo: 100% o más «Verde»; de 90% a menos de 100% «Amarillo»; menos de 90% «Rojo».","pista":"Dos SI anidados: =SI(D2>=1,\"Verde\",SI(D2>=0.9,\"Amarillo\",\"Rojo\"))"},{"celda":"E3","formula":"=SI(D3>=1,\"Verde\",SI(D3>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Amarillo","requiere":"SI(","texto":"<b>E3</b>: semáforo de Brenda."},{"celda":"E6","formula":"=SI(C6/B6>=1,\"Verde\",SI(C6/B6>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Rojo","requiere":"SI(","texto":"<b>E6</b>: semáforo de Elena. Como D6 está vacía, calcula el porcentaje dentro del SI (C6/B6).","explica":"Elena está en 87%: rojo. El semáforo no dice por qué; te dice con quién tienes que platicar primero."}]},{"tipo":"excel","rotulo":"Resumen del mes del equipo","datos":[["Persona","% cumplimiento","Faltas","Días programados","","Indicador","Valor"],["Andrea",1.05,0,24,"","Promedio del equipo",""],["Brenda",0.93,2,24,"","Personas que cumplen (100% o más)",""],["Carlos",0.84,3,24,"","Cumplimiento más bajo",""],["Diego",1,0,24,"","Total de faltas",""],["Elena",0.87,1,24,"","% de ausentismo",""],["Fernando",1.05,0,24,"","",""]],"retos":[{"celda":"G2","formula":"=PROMEDIO(B2:B7)","esperado":0.9566666666666667,"requiere":"PROMEDIO(","texto":"<b>G2</b>: promedio de cumplimiento del equipo."},{"celda":"G3","formula":"=CONTAR.SI(B2:B7,\">=1\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>G3</b>: ¿cuántas personas cumplieron (100% o más)?","pista":"El criterio va entre comillas: \">=1\"."},{"celda":"G4","formula":"=MIN(B2:B7)","esperado":0.84,"requiere":"MIN(","texto":"<b>G4</b>: el cumplimiento más bajo del equipo."},{"celda":"G5","formula":"=SUMA(C2:C7)","esperado":6,"requiere":"SUMA(","texto":"<b>G5</b>: total de faltas del mes."},{"celda":"G6","formula":"=REDONDEAR(G5/SUMA(D2:D7),3)","esperado":0.042,"requiere":"REDONDEAR(","texto":"<b>G6</b>: % de ausentismo = faltas entre días programados, redondeado a 3 decimales.","explica":"4.2% de ausentismo. Ojo: 5 de las 6 faltas son de Brenda, Carlos y Elena, justo quienes no llegaron a la meta. Vale la pena preguntar qué está pasando antes de sacar conclusiones."}]},{"tipo":"destacado","texto":"<b>El número abre la conversación, no la cierra.</b> Un promedio de 95.7% se ve bien, pero esconde a Carlos en 84%. Revisa siempre el promedio y también a cada persona, y usa los datos para preguntar («¿qué te está frenando?»), no para exhibir. No publiques los resultados individuales con nombre si tu empresa no lo autoriza."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para contar cuántos cumplieron la meta usas…","ops":["CONTAR.SI","PROMEDIO","MIN"],"correcta":0,"explica":"CONTAR.SI cuenta las celdas que cumplen un criterio."},{"p":"Un promedio del equipo en verde significa que…","ops":["Nadie necesita apoyo","Ya no hay que medir","Puede haber personas en rojo: revisa también a cada una"],"correcta":2}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el semáforo que nadie entendía</b><br>La supervisora de un call center en Mérida llevaba los indicadores de su equipo en la cabeza: «Pedro va bien, Ana va mal». Cuando RH le pidió datos para decidir un bono, no los tenía. Una compañera le armó una hoja con meta, real, porcentaje de cumplimiento y semáforo; descubrieron que Ana cumplía 96% y Pedro 78%, al revés de lo que ella creía.<br>Tres indicadores básicos: cumplimiento, calidad y asistencia. El dato abre la conversación; no la sustituye."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Si la meta es 250 llamadas y Pedro hizo 195, su cumplimiento es…","ops":["78%","22%","128%"],"correcta":0,"explica":"195 ÷ 250 = 0.78."},{"p":"¿Qué muestra el caso?","ops":["Que la percepción del jefe puede equivocarse sin datos","Que los datos no sirven","Que Pedro es mal trabajador"],"correcta":0,"explica":"Los datos corrigen sesgos."},{"p":"Con el dato de Pedro, lo siguiente es…","ops":["una conversación 1 a 1 para entender qué pasa","ignorarlo","un acta administrativa"],"correcta":0,"explica":"El dato abre la conversación."}]},{"tipo":"comparar","titulo":"Cómo se usa el dato","mal":"«Pedro, vas muy mal, ponte las pilas.»","bien":"«Pedro, este mes llevas 78% de la meta; en abril ibas en 95%. ¿Qué cambió? Cuéntame.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Diseña los tres indicadores de un equipo que conozcas (cumplimiento, calidad, asistencia): qué medirías y de dónde sacarías el dato.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe la fórmula del semáforo que usarías y los umbrales, y explica por qué esos.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Tablero del equipo","texto":"TABLERO DEL EQUIPO — [Mes]\nPersona | Meta | Real | % cumplimiento | Semáforo | Errores de calidad | Faltas\n[ ] | [ ] | [ ] | [=C2/B2] | [=SI(D2>=0.95,\"Verde\",SI(D2>=0.8,\"Amarillo\",\"Rojo\"))] | [ ] | [ ]\nPromedio del equipo: [=PROMEDIO(D2:D10)]\nPersonas en rojo: [=CONTAR.SI(E2:E10,\"Rojo\")]\nMínimo: [=MIN(D2:D10)]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Tres indicadores básicos: cumplimiento, calidad y asistencia.","% cumplimiento = real / meta; el semáforo se arma con SI anidados.","PROMEDIO, CONTAR.SI y MIN resumen al equipo; el dato abre la conversación."]}],"d-liderazgo-m3-l4":[{"tipo":"texto","texto":"La <b>junta 1 a 1</b> es una plática breve y periódica (por ejemplo, 20 minutos cada dos semanas) entre tú y cada persona de tu equipo. Es <b>su</b> espacio: para hablar de avances, obstáculos, ideas y desarrollo. Cuando existe, los problemas se detectan temprano y el bajo desempeño rara vez te toma por sorpresa."},{"tipo":"plantilla","rotulo":"Agenda de junta 1 a 1","texto":"JUNTA 1 A 1\nColaborador: [nombre]      Fecha: [__/__/____]      Duración: 20 min\n\n1. ¿Cómo estás? (2 min)\n2. Lo que tú quieras platicar primero (5 min)\n3. Avance de objetivos e indicadores (5 min): [dato de cumplimiento, calidad, asistencia]\n4. Obstáculos: ¿qué te está frenando? ¿qué necesitas de mí? (5 min)\n5. Reconocimiento o retroalimentación SBI (2 min)\n6. Acuerdos (1 min):\n   - Colaborador se compromete a: [...]\n   - Yo me comprometo a: [...]\n   - Próxima 1 a 1: [fecha]","nota":"No la canceles a la primera urgencia: si la mueves, reprográmala ese mismo día."},{"tipo":"tabla","titulo":"¿Por qué alguien no rinde? Diagnostica antes de actuar","encabezados":["Pregunta","Si la respuesta es «no»…"],"filas":[["¿Sabe qué se espera de él o ella?","Aclara la meta y el estándar (objetivo SMART)"],["¿Sabe cómo hacerlo?","Capacita, acompaña, dirige (estilo E1 o E2)"],["¿Puede hacerlo? (herramientas, tiempo, salud, carga)","Resuelve recursos, cargas o canaliza a RH o al servicio médico"],["¿Quiere hacerlo?","Explora motivación, conflictos o problemas personales; aplica consecuencias si ya se aclaró todo lo anterior"]]},{"tipo":"practica","rotulo":"Diagnostica","preguntas":[{"p":"Juan tiene bajo cumplimiento desde que cambiaron el sistema de captura y nadie lo capacitó. El problema es de…","ops":["Nada, ya se acostumbrará","Saber cómo hacerlo: toca capacitar","Querer: toca sancionar"],"correcta":1,"explica":"Sancionar lo que en realidad es falta de capacitación es injusto y no resuelve nada."},{"p":"Ana sabe hacer el trabajo pero su montacargas falla a diario. El problema es de…","ops":["Poder: faltan recursos en buen estado","Querer","Saber"],"correcta":0}]},{"tipo":"texto","texto":"Si después de hablarlo el problema sigue, se usa un <b>plan de mejora</b>: un acuerdo por escrito con metas concretas, apoyos y fechas de revisión. Su objetivo real es que la persona mejore, no «armar el expediente». Trabájalo con <b>Recursos Humanos</b>: cualquier sanción o rescisión se decide con RH y conforme al reglamento interior y la Ley Federal del Trabajo, nunca por tu cuenta."},{"tipo":"plantilla","rotulo":"Plan de mejora del desempeño","texto":"PLAN DE MEJORA DEL DESEMPEÑO\nColaborador: [nombre]      Puesto: [...]      Jefe inmediato: [...]\nFecha de inicio: [...]      Duración: [4 a 8 semanas]      RH enterado: [nombre]\n\n1. Situación actual (hechos y datos): [ej. cumplimiento promedio 84% en septiembre; 9 errores de calidad por semana]\n2. Meta esperada (SMART): [ej. 95% o más de la meta semanal y 3 errores o menos por semana, a partir de la semana 4]\n3. Apoyos que da la empresa: [capacitación, acompañamiento, ajuste de herramientas]\n4. Compromisos del colaborador: [...]\n5. Revisiones: [fechas semanales, en junta 1 a 1]\n6. Qué pasa si se cumple / si no se cumple: [según políticas de la empresa y RH]\n\nFirmas: Colaborador ____  Jefe ____  RH ____"},{"tipo":"excel","rotulo":"Seguimiento del plan de mejora de Carlos","datos":[["Semana","Meta","Piezas buenas","Errores de calidad","¿Cumple semana?","","Indicador","Valor"],["1",1200,1010,9,"","","Promedio de piezas (6 semanas)",""],["2",1200,1080,7,"","","Promedio últimas 3 semanas",""],["3",1200,1150,4,"","","Semanas con 3 errores o menos",""],["4",1200,1210,3,"","","Estado en la semana 6",""],["5",1200,1230,2,"","","",""],["6",1200,1190,2,"","","",""]],"retos":[{"celda":"E2","formula":"=SI(Y(C2>=B2*0.95,D2<=3),\"Sí\",\"No\")","esperado":"No","requiere":"Y(","texto":"<b>E2</b>: la semana cumple si las piezas son al menos 95% de la meta <b>y</b> hay 3 errores o menos. Usa SI con Y.","pista":"=SI(Y(C2>=B2*0.95, D2<=3), \"Sí\", \"No\")"},{"celda":"E5","formula":"=SI(Y(C5>=B5*0.95,D5<=3),\"Sí\",\"No\")","esperado":"Sí","requiere":"Y(","texto":"<b>E5</b>: ¿cumple la semana 4?"},{"celda":"H2","formula":"=PROMEDIO(C2:C7)","esperado":1145,"requiere":"PROMEDIO(","texto":"<b>H2</b>: promedio de piezas buenas en las 6 semanas."},{"celda":"H3","formula":"=PROMEDIO(C5:C7)","esperado":1210,"requiere":"PROMEDIO(","texto":"<b>H3</b>: promedio solo de las semanas 4 a 6.","explica":"El promedio general (1145) esconde la mejora: en las últimas tres semanas Carlos ya está arriba de la meta."},{"celda":"H4","formula":"=CONTAR.SI(D2:D7,\"<=3\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>H4</b>: ¿cuántas semanas tuvo 3 errores o menos?"},{"celda":"H5","formula":"=SI(O(D7>5,C7<B7*0.9),\"Alerta\",\"En camino\")","esperado":"En camino","requiere":"O(","texto":"<b>H5</b>: marca «Alerta» si en la semana 6 hubo más de 5 errores <b>o</b> menos de 90% de la meta; si no, «En camino». Usa SI con O."}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el plan de mejora que era un despido anunciado</b><br>Un jefe de mantenimiento en una planta de Silao decidió que un técnico «ya no servía». Le dio un «plan de mejora» con metas imposibles en dos semanas, sin capacitación, y le dijo que si no cumplía «se iba». No habló con RH. El técnico, en realidad, no sabía usar el equipo nuevo que llegó hacía un mes.<br>Antes de actuar, diagnostica: ¿sabe qué se espera?, ¿sabe hacerlo?, ¿puede?, ¿quiere? El plan de mejora busca que la persona mejore y se trabaja con RH."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál era la causa real del bajo desempeño?","ops":["Falta de ganas","No sabía usar el equipo nuevo","Mala actitud"],"correcta":1,"explica":"Si no sabe, la solución es capacitar."},{"p":"¿Qué falló en el «plan de mejora»?","ops":["Metas imposibles, sin apoyo y sin RH","Que tenía fechas","Que era por escrito"],"correcta":0,"explica":"Un plan real da apoyo, metas alcanzables y seguimiento."},{"p":"¿Puede el jefe despedir por su cuenta?","ops":["Solo si está enojado","Sí, siempre","No: se trabaja con RH y conforme a la ley"],"correcta":2,"explica":"Los despidos tienen implicaciones legales."}]},{"tipo":"comparar","titulo":"Cómo se abre la 1 a 1","mal":"«Ya no sirves, tienes dos semanas o te vas.»","bien":"«Desde que llegó el equipo nuevo, tus órdenes cerradas bajaron de 12 a 7 por semana. ¿Qué se te complica? ¿Qué necesitas para dominarlo?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Aplica las cuatro preguntas de diagnóstico (¿sabe qué se espera?, ¿sabe?, ¿puede?, ¿quiere?) a un caso de bajo desempeño que conozcas, y escribe qué harías según la respuesta.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe la agenda de tus juntas 1 a 1 de 20 minutos y con qué frecuencia las harías.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Plan de mejora","texto":"PLAN DE MEJORA — [Persona]\nSituación con datos: [ ]\nDiagnóstico: ¿sabe qué se espera? [ ] ¿sabe? [ ] ¿puede? [ ] ¿quiere? [ ]\nMeta alcanzable: [ ]\nApoyo que daré: [capacitación, acompañamiento, recursos]\nRevisiones: [fechas]\nRH enterado: [nombre, fecha]\n\nAGENDA 1 A 1 (20 min): cómo estás · avances · obstáculos · retroalimentación · acuerdos","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["La 1 a 1 periódica detecta los problemas temprano.","Antes de actuar diagnostica: ¿sabe qué se espera?, ¿sabe?, ¿puede?, ¿quiere?","El plan de mejora busca que la persona mejore y se trabaja con RH; tú no despides por tu cuenta."]}],"d-liderazgo-m3-lab":[{"tipo":"destacado","texto":"Coordinas a 6 ejecutivos de ventas en <b>Seguros Horizonte</b>, en Guadalajara. Tu director te pide «subir las ventas» este trimestre. Tienes los datos: el trimestre pasado vendieron 90 pólizas; uno de los ejecutivos, Marco, vendió solo 5 cuando la meta individual era 15."},{"tipo":"texto","texto":"<p><b>Escena 1 — La meta.</b> «Subir las ventas» no es un objetivo.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe el objetivo SMART del trimestre y su reparto por persona.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — La delegación.</b> Tienes demasiadas tareas administrativas.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe qué delegarías, a quién y con qué nivel de autoridad.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — El tablero.</b> Necesitas ver el avance cada semana.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Describe tu tablero: columnas, fórmulas y semáforo.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — Marco.</b> Tiene 33% de cumplimiento.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe el diagnóstico con las cuatro preguntas y el plan de mejora.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"Cumplimiento de Marco:","ops":["5%","33%","67%"],"correcta":1,"explica":"5 ÷ 15 ≈ 0.33."},{"p":"Si el objetivo es 108 pólizas (20% más), el reparto parejo es…","ops":["20 por ejecutivo","18 por ejecutivo","15 por ejecutivo"],"correcta":1,"explica":"108 ÷ 6 = 18."},{"p":"Con Marco, el primer paso es…","ops":["reasignar su cartera sin hablar","una 1 a 1 para diagnosticar la causa","un acta"],"correcta":1,"explica":"El dato abre la conversación."}]},{"tipo":"plantilla","rotulo":"Tablero trimestral","texto":"TABLERO — [Trimestre]\nPersona | Meta | Semana 1 | … | Acumulado | % | Semáforo\nObjetivo SMART del equipo: [ ]\nDelegaciones activas: [ ]\nPlanes de mejora: [ ]","nota":"Cópiala y úsala en tu trabajo."}],"d-liderazgo-m4-l1":[{"tipo":"texto","texto":"No puedes «inyectar» motivación, pero sí puedes crear condiciones para que aparezca o para que se apague. El psicólogo <b>Frederick Herzberg</b> (1959) propuso distinguir dos grupos de factores: los <b>higiénicos</b>, cuya falta genera insatisfacción (sueldo, condiciones, trato del jefe, políticas), y los <b>motivadores</b>, que generan satisfacción real (logro, reconocimiento, el trabajo en sí, responsabilidad, crecimiento)."},{"tipo":"tabla","titulo":"Lo que puedes mover como mando medio","encabezados":["Factor","Qué depende de ti"],"filas":[["Trato del jefe (higiénico)","Respeto, justicia, cumplir lo que prometes"],["Condiciones (higiénico)","Pedir a tiempo herramientas, equipo de protección, reparaciones"],["Logro (motivador)","Metas claras y alcanzables; que la gente vea su avance"],["Reconocimiento (motivador)","Decir concretamente qué se hizo bien, con frecuencia"],["Responsabilidad y crecimiento (motivadores)","Delegar, enseñar, proponer a alguien para una capacitación"]],"nota":"El sueldo lo decide la empresa, pero cómo tratas a tu gente lo decides tú todos los días."},{"tipo":"texto","texto":"<b>Daniel Pink</b>, en su libro <i>Drive</i> (2009), resume la motivación para trabajos que requieren pensar en tres elementos: <b>autonomía</b> (algo de control sobre cómo hago mi trabajo), <b>maestría</b> (sentir que mejoro) y <b>propósito</b> (saber para qué sirve lo que hago). Ejemplo: en un hospital, explicarle a la camillera que su puntualidad hace que el quirófano arranque a tiempo le da propósito a su trabajo."},{"tipo":"comparar","titulo":"Reconocimiento que no sirve vs el que sí","malTitulo":"No sirve","mal":"Un «gracias a todos» al final del mes, igual para quien se esforzó y para quien no.","bienTitulo":"Sí sirve","bien":"«Lupita, el sábado reacomodaste la bodega de lácteos y ya no tuvimos producto caducado en anaquel. Eso nos ahorró mermas y quejas. Gracias.» Concreto, oportuno y sincero."},{"tipo":"tarjetas","rotulo":"Formas de reconocer que no cuestan","tarjetas":[{"frente":"Un mensaje concreto","reverso":"Escríbelo el mismo día: qué hizo y qué impacto tuvo."},{"frente":"Frente al equipo","reverso":"En la junta de arranque, si a la persona no le incomoda."},{"frente":"Hacia arriba","reverso":"Menciona su nombre con tu jefe: «esto lo resolvió Juan»."},{"frente":"Confianza","reverso":"Encargarle algo retador también es una forma de reconocer."},{"frente":"Escuchar su idea","reverso":"Y si la aplicas, decir que fue suya."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Según Herzberg, un sueldo justo y buenas condiciones…","ops":["Son lo único que motiva","No importan","Evitan la insatisfacción, pero por sí solos no motivan"],"correcta":2,"explica":"Son necesarios pero no suficientes."},{"p":"Un buen reconocimiento es…","ops":["Solo con dinero","Concreto, oportuno y sincero","Genérico y anual"],"correcta":1},{"p":"Explicar para qué sirve un trabajo alimenta el…","ops":["Propósito","Salario","Horario"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el bono que no motivó a nadie</b><br>Una empresa de paquetería en Tijuana dio un bono de $500 a todos los repartidores por igual para «motivarlos». Un mes después, la rotación seguía alta. En las entrevistas de salida decían: «nadie te dice gracias», «las rutas cambian sin avisar» y «no hay forma de crecer». Una supervisora que reconocía a su gente cada semana tenía la mitad de rotación.<br>Los factores higiénicos (sueldo, condiciones) evitan insatisfacción; los motivadores (logro, reconocimiento, crecimiento) generan compromiso. Reconoce concreto, pronto y sincero."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Según Herzberg, el sueldo es…","ops":["irrelevante","un factor higiénico: si falla, genera insatisfacción","el principal motivador"],"correcta":1,"explica":"Resolver lo higiénico no basta para comprometer."},{"p":"¿Qué hacía distinta a la supervisora?","ops":["Era más estricta","Pagaba más","Reconocía de forma concreta y frecuente"],"correcta":2,"explica":"El reconocimiento no cuesta dinero."},{"p":"Autonomía, maestría y propósito son ideas de…","ops":["Hersey y Blanchard","Kotter","Daniel Pink"],"correcta":2,"explica":"Son fuentes de motivación intrínseca."}]},{"tipo":"comparar","titulo":"Cómo se reconoce","mal":"«Buen trabajo, equipo.» (una vez al año)","bien":"«Luis, ayer sacaste 42 entregas sin una sola queja, en la ruta más difícil. Gracias; así se sostiene la operación.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Pregunta a tres personas qué las motiva en su trabajo (o recuerda lo que te motiva a ti) y clasifica las respuestas en factores higiénicos y motivadores.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Diseña cinco formas de reconocimiento sin costo para un equipo que conozcas.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Plan de reconocimiento","texto":"RECONOCIMIENTO SIN COSTO\n□ Gracias concreto y pronto (SBI)\n□ Mención en la junta de arranque\n□ Mensaje al jefe de mi jefe con copia a la persona\n□ Elegir un proyecto que le interese\n□ Enseñar a otros lo que domina\n\nRegistro semanal: Persona | Qué hizo | Cómo lo reconocí | Fecha\nMeta: reconocer a cada persona al menos [ ] veces al mes.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Herzberg: factores higiénicos evitan insatisfacción; los motivadores generan compromiso.","Autonomía, maestría y propósito (Pink).","Reconoce concreto, pronto y sincero; no cuesta dinero."]}],"d-liderazgo-m4-l2":[{"tipo":"texto","texto":"Donde hay personas hay conflictos: por turnos, por cargas de trabajo, por malentendidos, por formas distintas de trabajar. El conflicto no es malo en sí; lo dañino es <b>ignorarlo</b> o dejar que se vuelva personal. Tu papel es atenderlo pronto y con imparcialidad."},{"tipo":"tabla","titulo":"Cinco formas de manejar un conflicto (modelo de Thomas y Kilmann)","encabezados":["Forma","Qué es","Cuándo sirve"],"filas":[["Competir","Imponer tu posición","Emergencias, seguridad, reglas no negociables"],["Colaborar","Buscar juntos una solución que sirva a ambos","Temas importantes con tiempo para hablar"],["Transigir (ceder un poco cada uno)","Punto medio","Cuando hay que decidir pronto y ambas partes tienen razón en parte"],["Evitar","Posponer o no entrar","Temas menores o cuando hace falta enfriar los ánimos"],["Complacer","Ceder a lo que pide el otro","Cuando el tema importa más al otro que a ti"]]},{"tipo":"pasos","rotulo":"Mediar entre dos personas de tu equipo","pasos":["Habla primero con cada una <b>por separado</b> y escucha su versión sin tomar partido.","Reúnelas en privado. Pon reglas: hablar por turnos, sin insultos, de hechos.","Que cada una explique qué necesita (no solo qué le molesta).","Busquen opciones juntas; tú propones solo si se atoran.","Acuerden algo concreto y fecha para revisar.","Si hay acoso, amenazas o violencia, <b>no es un conflicto para mediar</b>: canaliza a RH según el protocolo de la empresa."]},{"tipo":"practica","rotulo":"Caso: call center en Monterrey","preguntas":[{"p":"Dos agentes discuten porque una siempre toma el descanso a la hora que la otra quiere. Lo mejor es…","ops":["Ignorarlo, ya se les pasará","Darle la razón a la que tenga más antigüedad","Escuchar a ambas y acordar un rol de descansos claro"],"correcta":2,"explica":"Un problema de reglas se resuelve con reglas claras."},{"p":"Sale un simulacro de evacuación y un agente dice que no va a salir porque está en llamada. Usas…","ops":["Evitar","Competir: la seguridad no se negocia","Colaborar con calma"],"correcta":1},{"p":"Una agente te dice que un compañero le manda mensajes con insinuaciones sexuales. Tú…","ops":["La escuchas, no la juzgas y canalizas a RH según el protocolo","Los sientas a los dos a mediar","Le dices que no le haga caso"],"correcta":0,"explica":"Eso no es un simple conflicto: puede ser acoso sexual y requiere el procedimiento formal."}]},{"tipo":"relacionar","rotulo":"Relaciona","pares":[["Buscar una solución que sirva a ambos","Colaborar"],["Cada uno cede un poco","Transigir"],["Imponer tu posición","Competir"],["Posponer para enfriar ánimos","Evitar"]]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: las vacaciones de diciembre</b><br>En una tienda de electrónica en Querétaro, dos vendedores pelean por las vacaciones de Navidad. Se dejaron de hablar y el ambiente se tensó. El gerente evitó el tema «para que se arreglen solos». Mientras tanto, otra vendedora le contó que un compañero le manda mensajes insinuantes y no sabe qué hacer.<br>El conflicto se atiende pronto, en privado y con imparcialidad. Hay cinco formas de manejarlo según el caso. El acoso o la violencia no se median: se canalizan a RH."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué forma de manejo conviene para las vacaciones?","ops":["Competir: decide el jefe sin escuchar","Colaborar o transigir: buscar un acuerdo justo con criterios claros","Evitar el tema"],"correcta":1,"explica":"Hay intereses de ambos que pueden conciliarse."},{"p":"Los mensajes insinuantes son…","ops":["posible acoso: se canaliza a RH y se protege a quien reporta","algo personal","un conflicto que se media entre los dos"],"correcta":0,"explica":"El acoso no se trata como un desacuerdo."},{"p":"¿Por qué no conviene «que se arreglen solos»?","ops":["Porque el conflicto crece y afecta a todo el equipo","Porque no le toca","Porque es más rápido"],"correcta":0,"explica":"Atender pronto evita que escale."}]},{"tipo":"comparar","titulo":"Cómo se media el conflicto","mal":"«Arréglense ustedes, yo no me meto.»","bien":"«Los dos quieren la misma semana. Propongo criterio: quien no la tuvo el año pasado elige primero, y el otro toma Año Nuevo. ¿Les parece justo o proponen otra forma?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe un conflicto de trabajo que conozcas, qué forma de manejo se usó y cuál habría sido mejor, y por qué.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cómo responderías a una persona que te cuenta que vive acoso de un compañero: qué dices, qué no dices y a quién canalizas.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Guía para conflictos","texto":"CONFLICTO EN EL EQUIPO\n1. ¿Es acoso, violencia o discriminación? → No mediar: canalizar a RH y proteger a quien reporta.\n2. Si es un desacuerdo: hablar con cada parte en privado.\n3. Identificar intereses (qué necesita cada uno), no solo posiciones.\n4. Elegir forma: colaborar · transigir · competir (urgencias) · evitar (temas menores) · complacer (cuando el otro tiene razón).\n5. Acuerdo escrito y seguimiento: [fecha]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["El conflicto se atiende pronto, en privado y con imparcialidad.","Cinco formas: competir, colaborar, transigir, evitar y complacer; se elige según el caso.","El acoso o la violencia no se median: se canalizan a RH."]}],"d-liderazgo-m4-l3":[{"tipo":"texto","texto":"<b>Amy Edmondson</b>, profesora de Harvard, definió la <b>seguridad psicológica</b> (en un estudio de 1999) como la creencia compartida en un equipo de que es seguro asumir riesgos interpersonales: preguntar, admitir un error, dar una idea o decir «no estoy de acuerdo» sin miedo a ser humillado o castigado. No significa que todo se vale ni que no haya exigencia: significa que <b>se puede hablar</b>."},{"tipo":"texto","texto":"¿Por qué te importa? Porque si tu gente tiene miedo, <b>esconde los errores</b>. En una planta, el operador que no reporta que la guarda está floja; en un hospital, la enfermera que no pregunta si la dosis es correcta. Los problemas no desaparecen: te enteras tarde y más caros."},{"tipo":"comparar","titulo":"Cómo reaccionas ante un error reportado","malTitulo":"Destruye la seguridad","mal":"«¿Otra vez? ¿Pues en qué estabas pensando? Esto va a tu expediente.»","bienTitulo":"Construye seguridad","bien":"«Gracias por avisar a tiempo. Primero contengamos: separa el lote. Luego vemos qué falló en el proceso para que no se repita.»"},{"tipo":"lista","items":["Admite tus propios errores frente al equipo.","Pregunta «¿qué opinan?» y espera la respuesta, aunque haya silencio.","Agradece a quien trae malas noticias.","Separa el error honesto de la negligencia o la falta repetida.","Nunca te burles de una pregunta."]},{"tipo":"texto","texto":"<b>Diversidad e inclusión.</b> Tu equipo puede tener personas de distintas edades, orígenes, religiones, con alguna discapacidad, mujeres en puestos tradicionalmente masculinos, personas LGBT+, madres y padres con cuidados a su cargo. La <b>Ley Federal del Trabajo (art. 3)</b> prohíbe establecer condiciones que discriminen por origen étnico o nacional, género, edad, discapacidad, condición social, condiciones de salud, religión, opiniones, preferencias sexuales o estado civil, entre otros motivos. Y el art. 133 prohíbe, por ejemplo, exigir certificados de no embarazo."},{"tipo":"practica","rotulo":"¿Inclusión o discriminación?","preguntas":[{"p":"Asignar las horas extra solo a hombres «porque aguantan más».","ops":["Criterio válido","Discriminación por género","Decisión operativa válida del jefe","Acción afirmativa"],"correcta":1,"explica":"Repartir horas extra por sexo es discriminación por género; se asignan con criterios de puesto y capacidad."},{"p":"Ajustar la estación de trabajo para un operador en silla de ruedas.","ops":["Privilegio por antigüedad","Trato preferente injusto","Inclusión","Ajuste opcional que la empresa puede negar"],"correcta":2,"explica":"Adaptar la estación para que una persona con discapacidad trabaje en igualdad de condiciones es inclusión, no un trato preferente."},{"p":"Hacer chistes sobre la edad del compañero de 60 años en la junta.","ops":["Humor sin importancia","Convivencia sana entre compañeros","Asunto personal que no le toca al jefe","Trato discriminatorio que el jefe debe frenar"],"correcta":3,"explica":"Burlarse de la edad de alguien es trato discriminatorio, y el jefe tiene la responsabilidad de frenarlo en el momento."}]},{"tipo":"reflexion","rotulo":"Tu equipo hoy","pregunta":"¿En tu equipo la gente reporta errores y opina, o se queda callada? Escribe una señal que lo demuestre y una conducta tuya que vas a cambiar o reforzar.","ayuda":"Señal: … Conducta que voy a…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el error que nadie reportó</b><br>En un laboratorio clínico de Puebla, una técnica se dio cuenta de que había etiquetado mal dos muestras. No dijo nada porque la última vez que alguien reportó un error, el jefe lo regañó delante de todos. El resultado equivocado llegó a un paciente. Además, en el mismo equipo se hacían chistes sobre el acento de una compañera de Chiapas.<br>Seguridad psicológica: poder hablar sin miedo, con exigencia. Si hay miedo, los errores se esconden. La ley prohíbe discriminar y el jefe frena tratos y chistes discriminatorios."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Por qué la técnica no reportó el error?","ops":["Porque no se dio cuenta","Porque no le importaba","Por miedo a ser humillada, como vio que pasó antes"],"correcta":2,"explica":"El regaño público enseñó al equipo a callar."},{"p":"Seguridad psicológica significa…","ops":["que no hay reglas","que se puede hablar y reportar sin miedo, manteniendo la exigencia","que nadie recibe retroalimentación"],"correcta":1,"explica":"No es permisividad: es confianza para decir la verdad."},{"p":"Ante los chistes sobre el acento, el jefe…","ops":["se ríe para no romper el ambiente","los frena con claridad y en el momento","no hace nada si ella no se queja"],"correcta":1,"explica":"Tolerar la discriminación la normaliza."}]},{"tipo":"comparar","titulo":"Cómo se responde a un error reportado","mal":"«¿Cómo es posible? ¡Qué descuido!» (frente a todos)","bien":"«Gracias por decirlo a tiempo. Vamos a corregir esas dos muestras ahora y luego revisamos juntos qué del proceso permitió el error.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe tres conductas del jefe que destruyen la seguridad psicológica y tres que la construyen, con ejemplos concretos.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe lo que dirías en el momento si escuchas un chiste discriminatorio en tu equipo.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Termómetro de seguridad psicológica","texto":"TERMÓMETRO — pregunta al equipo (anónimo, de 1 a 5)\n1. Si cometo un error, no se usa en mi contra.\n2. Puedo plantear problemas y temas difíciles.\n3. Aquí no se rechaza a las personas por ser diferentes.\n4. Es seguro tomar un riesgo razonable.\n5. Es fácil pedir ayuda.\n\nPromedio: [ ]  Acciones: [ ]\nEn el momento de un error: agradecer · corregir · revisar el proceso, no a la persona.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Seguridad psicológica: poder hablar sin miedo, con exigencia (Edmondson).","Si hay miedo, los errores se esconden y te llegan tarde.","La LFT prohíbe discriminar: el jefe frena tratos y chistes discriminatorios."]}],"d-liderazgo-m4-l4":[{"tipo":"texto","texto":"La <b>NOM-035-STPS-2018</b> obliga a los centros de trabajo a identificar y prevenir los factores de riesgo psicosocial y la violencia laboral. No necesitas ser experto en la norma (para eso existe un diplomado aparte), pero sí debes saber algo: entre los factores de riesgo que la norma reconoce están el <b>liderazgo negativo y las relaciones negativas en el trabajo</b>, las <b>cargas de trabajo</b>, la <b>falta de control</b> sobre el trabajo, las <b>jornadas</b> y la <b>interferencia trabajo-familia</b>. Muchos de esos pasan por tus manos."},{"tipo":"tabla","titulo":"Tu papel como jefe","encabezados":["Qué hacer","Ejemplo"],"filas":[["Repartir cargas y horarios con criterio","No cargarle siempre las horas extra al mismo"],["Dar claridad y algo de control","Explicar funciones y dejar decidir cómo organizarse"],["Prevenir la violencia laboral","Frenar gritos, humillaciones, burlas y apodos ofensivos"],["Detectar y canalizar","Notar cambios (aislamiento, faltas, errores) y ofrecer apoyo o canalizar a RH o al servicio médico"],["Acontecimientos traumáticos severos","Tras un accidente grave o un asalto, avisar a RH para que la persona sea identificada y canalizada"],["Respetar el canal de quejas","Nunca tomar represalias contra quien se queja de buena fe"]],"nota":"No diagnostiques ni hagas de psicólogo: tu trabajo es notar, escuchar y canalizar."},{"tipo":"texto","texto":"<b>Lo que dice la Ley Federal del Trabajo.</b> El art. 3 Bis define el <b>hostigamiento</b> (ejercicio del poder en una relación de subordinación, con conductas verbales, físicas o ambas) y el <b>acoso sexual</b>. El art. 133 prohíbe a los patrones <i>y a sus representantes</i> realizar o tolerar hostigamiento o acoso sexual. Y el art. 11 considera <b>representantes del patrón</b> a quienes ejercen funciones de dirección o administración: lo que tú haces como jefe compromete a la empresa."},{"tipo":"destacado","texto":"<b>Tú no despides por tu cuenta.</b> Aunque tengas el enojo o la razón, una rescisión mal hecha (sin causa justificada ni aviso por escrito conforme a la ley) puede costarle a la empresa un juicio y una indemnización. Si hay una falta grave, documenta los hechos y lleva el caso a <b>Recursos Humanos</b> de inmediato. Frases como «estás despedido» o «si no firmas tu renuncia te va peor» no te corresponden y pueden ser ilegales."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un jefe de turno les grita y pone apodos humillantes a sus operadores «para que reaccionen». Según la NOM-035 eso es…","ops":["Un estilo de liderazgo válido","Asunto privado del jefe","Violencia laboral que debe prevenirse"],"correcta":2,"explica":"Además, al ser representante del patrón compromete a la empresa."},{"p":"Un cajero fue asaltado ayer en ventanilla. Tú…","ops":["Lo diagnosticas con estrés postraumático","Avisas a RH para identificarlo y canalizarlo a atención","Le dices que ya pasó y que siga trabajando"],"correcta":1,"explica":"Es un acontecimiento traumático severo según la NOM-035."},{"p":"Descubres que un operador llegó en estado de ebriedad. Lo correcto es…","ops":["Retirarlo de la operación por seguridad, documentar y llevar el caso a RH","Despedirlo tú en ese momento","Ignorarlo"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El art. 11 de la LFT considera a los jefes ___ del patrón.","resp":["representantes","representante"]},{"frase":"Tras un accidente grave, el jefe detecta y ___ a la persona para que reciba atención.","resp":["canaliza"]},{"frase":"Ante una falta grave, el jefe documenta y lleva el caso a ___.","resp":["RH","Recursos Humanos","recursos humanos"]}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el jefe que gritaba «para que rindan»</b><br>El jefe de producción de una fábrica de calzado en León grita, cambia turnos sin avisar y dice que «así se ha hecho siempre». En la evaluación de la NOM-035, su área salió con el nivel de riesgo más alto por liderazgo negativo. Cuando una trabajadora le dijo que se sentía muy ansiosa, él le contestó: «eso es depresión, ve al psiquiatra» delante de otros.<br>El liderazgo negativo es un factor de riesgo psicosocial en la NOM-035. El jefe nota, escucha y canaliza; no diagnostica ni toma represalias. No despide por su cuenta: va con RH."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Según la NOM-035, los gritos y cambios sin aviso son…","ops":["problemas personales del trabajador","estilo de gestión aceptable","parte del liderazgo negativo, un factor de riesgo psicosocial"],"correcta":2,"explica":"El jefe puede prevenirlos con su conducta."},{"p":"¿Qué error cometió con la trabajadora ansiosa?","ops":["Mandarla con RH","Escucharla","Diagnosticar y exhibir su situación frente a otros"],"correcta":2,"explica":"El jefe no diagnostica y cuida la confidencialidad."},{"p":"¿Qué debió hacer?","ops":["Darle días libres sin registro","Escucharla en privado y canalizarla a RH o al servicio de salud","Ignorarla"],"correcta":1,"explica":"Notar, escuchar y canalizar."}]},{"tipo":"comparar","titulo":"Cómo se responde en privado","mal":"«Eso es depresión, ve al psiquiatra.» (frente a todos)","bien":"«Gracias por confiarme esto. No soy quien para decirte qué tienes, pero sí puedo acompañarte con RH para que te orienten. ¿Hay algo del trabajo que esté pesando y que podamos ajustar?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Revisa tu conducta como jefe (o la de uno que conozcas) contra los factores de liderazgo negativo de la NOM-035 y escribe dos cambios concretos.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe el procedimiento que seguirías si una persona de tu equipo te cuenta que está pasando por un mal momento emocional.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"El jefe ante la NOM-035","texto":"MI PAPEL ANTE LA NOM-035\nPrevengo: instrucciones claras · cambios avisados · carga razonable · trato respetuoso · reconocimiento.\nNoto: cambios de conducta, ausencias, errores nuevos.\nEscucho: en privado, sin juzgar.\nCanalizo: a RH / servicio médico: [nombre y contacto]\nNo hago: diagnosticar · exhibir · tomar represalias · despedir por mi cuenta.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["El liderazgo negativo es un factor de riesgo psicosocial en la NOM-035: tú puedes prevenirlo.","Nota, escucha y canaliza; no diagnostiques ni tomes represalias.","Como representante del patrón, no hostigas ni toleras acoso y no despides por tu cuenta: vas con RH."]}],"d-liderazgo-m4-lab":[{"tipo":"destacado","texto":"Eres coordinadora de enfermería en <b>Hospital Santa Fe</b>, en Querétaro. La dirección anuncia turnos de 12 horas. Dos enfermeras discuten a gritos por la asignación de pacientes, una más te dice que se siente agotada y sin ganas de nada, y en la última evaluación de la NOM-035 tu área salió alta en «carga de trabajo»."},{"tipo":"texto","texto":"<p><b>Escena 1 — El cambio de turnos.</b> El equipo está en contra.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe cómo comunicarías el cambio y cómo escucharías al equipo.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — La discusión.</b> Las dos enfermeras gritan en el pasillo.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe qué haces en el momento y después.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — La enfermera agotada.</b> Te lo dice llorando.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe cómo la escuchas y a dónde la canalizas, sin diagnosticar.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — La NOM-035.</b> Te piden tres acciones para reducir la carga.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe tres acciones concretas con responsable e indicador.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"Ante la discusión a gritos en el pasillo…","ops":["sancionar a ambas sin escuchar","separar en el momento y hablar con cada una en privado después","dejarlas terminar"],"correcta":1,"explica":"Primero calmar, luego atender el fondo."},{"p":"Con la enfermera agotada…","ops":["darle el día sin avisar a nadie","decirle que es depresión","escuchar en privado y canalizar al servicio de salud o RH"],"correcta":2,"explica":"No diagnosticas; canalizas."},{"p":"Para el cambio de turnos, una victoria rápida sería…","ops":["probar en un piso y mostrar resultados antes de extenderlo","no hacer nada","imponerlo en todos los pisos el lunes"],"correcta":0,"explica":"El piloto da evidencia y confianza."}]},{"tipo":"plantilla","rotulo":"Plan de clima y cambio","texto":"PLAN — [Área]\nCambio: por qué · piloto · capacitación · victoria rápida\nConflictos: acuerdos y seguimiento\nCanalizaciones (confidencial): [solo número y fecha]\nAcciones NOM-035: acción · responsable · indicador · fecha","nota":"Cópiala y úsala en tu trabajo."}],"d-liderazgo-m5-l1":[{"tipo":"texto","texto":"Nuevo sistema de nómina, otra línea de producto, cambio de horarios, fusión de sucursales: como mando medio te toca <b>aterrizar</b> cambios que muchas veces no decidiste. La resistencia es normal: la gente teme perder algo (su puesto, su dominio del trabajo, su rutina, su grupo) y muchas veces no entiende el porqué."},{"tipo":"texto","texto":"<b>Kurt Lewin</b> describió el cambio en tres etapas: <b>descongelar</b> (hacer ver que lo actual ya no sirve), <b>cambiar</b> (aprender la nueva forma) y <b>recongelar</b> (volverla la nueva costumbre). <b>John Kotter</b>, en <i>Leading Change</i> (1996), propuso ocho pasos para las organizaciones; varios se aplican a tu escala: crear sentido de urgencia, comunicar la visión, quitar obstáculos y conseguir <b>victorias rápidas</b>."},{"tipo":"pasos","rotulo":"Aterrizar un cambio con tu equipo","pasos":["<b>Explica el porqué</b> con datos y sin tecnicismos. Si no sabes el porqué, pregúntale a tu jefe antes de anunciarlo.","<b>Di qué cambia y qué no</b>: reduce la incertidumbre.","<b>Escucha los miedos</b> y responde lo que sepas; lo que no sepas, dilo y averígualo.","<b>Capacita antes</b> de exigir, y acepta que al principio bajará el rendimiento.","<b>Busca aliados</b>: personas respetadas del equipo que prueben primero.","<b>Celebra las primeras victorias</b> y corrige rápido lo que no funcione."]},{"tipo":"comparar","titulo":"Anunciar un cambio","malTitulo":"Así no","mal":"«De arriba dicen que desde el lunes usamos terminales para surtir pedidos. No sé por qué, pero así es. Ni modo.»","bienTitulo":"Así sí","bien":"«Desde el lunes surtiremos con terminales portátiles. El año pasado tuvimos 4% de pedidos con errores y cada uno nos cuesta devoluciones. Con la terminal, el sistema te avisa si tomas el producto equivocado. Esta semana hay capacitación en cada turno y los primeros días voy a estar en piso para apoyar. ¿Qué dudas tienen?»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La razón más común de resistencia al cambio es…","ops":["Que la gente es floja","Que el jefe es nuevo","El miedo a perder algo y no entender el porqué"],"correcta":2,"explica":"Por eso explicar y escuchar reduce la resistencia."},{"p":"Si no sabes por qué se hace un cambio, antes de anunciarlo…","ops":["Dices «ni modo, así es»","Preguntas a tu jefe","Inventas una razón"],"correcta":1},{"p":"Las «victorias rápidas» sirven para…","ops":["Demostrar que el cambio funciona y ganar confianza","Terminar antes","Evitar capacitar"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena las etapas de Lewin","items":[{"frase":"Descongelar cambiar y recongelar","es":"Las tres etapas del cambio"}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el sistema nuevo que nadie quería</b><br>Una cadena de farmacias en Chihuahua cambió de sistema de punto de venta. El gerente regional mandó un correo un viernes: «A partir del lunes se usa el sistema nuevo». No explicó por qué ni capacitó. Las filas crecieron, los empleados buscaban «trucos» para volver al sistema viejo y dos gerentes de sucursal dijeron que el sistema «no servía».<br>La resistencia al cambio es normal: miedo a perder y falta de un porqué. Explica, escucha, capacita antes de exigir y celebra los primeros logros."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué etapa de Lewin se saltó el gerente?","ops":["Ninguna","Recongelar","Descongelar: explicar el porqué y preparar a la gente"],"correcta":2,"explica":"Sin descongelar, la gente se aferra a lo conocido."},{"p":"¿Por qué buscaban volver al sistema viejo?","ops":["Porque el nuevo es peor","Porque son flojos","Miedo a equivocarse y no saber usar el nuevo"],"correcta":2,"explica":"Sin capacitación, el cambio genera miedo."},{"p":"Una «victoria rápida» en este caso sería…","ops":["cambiar de nuevo de sistema","mostrar que una sucursal piloto redujo el tiempo de cobro","castigar a quien use el viejo"],"correcta":1,"explica":"Los primeros logros visibles dan confianza."}]},{"tipo":"comparar","titulo":"Cómo se anuncia el cambio","mal":"«A partir del lunes se usa el sistema nuevo.»","bien":"«Cambiamos de sistema porque el actual deja de tener soporte y nos hace perder ventas. Primero lo prueba la sucursal Centro dos semanas; todos tendrán capacitación antes de usarlo y un número de ayuda.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Recuerda un cambio en tu trabajo o tu vida que haya generado resistencia. Escribe qué faltó explicar, escuchar o capacitar.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Diseña cómo llevarías a tu equipo a través de un cambio próximo usando los pasos de Kotter que apliquen.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Plan para liderar un cambio","texto":"CAMBIO — [Qué cambia]\nPor qué (urgencia real): [ ]\nCómo se verá cuando funcione (visión): [ ]\nQué pierde o teme la gente: [ ]\nCómo escucharé: [ ]\nCapacitación antes de exigir: [ ]\nObstáculos que quitaré: [ ]\nVictoria rápida y cómo la celebraré: [ ]\nCómo lo volveremos costumbre: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["La resistencia al cambio es normal: miedo a perder y falta de porqué.","Lewin: descongelar, cambiar, recongelar; Kotter: urgencia, visión, obstáculos, victorias rápidas.","Explica, escucha, capacita antes de exigir y celebra los primeros logros."]}],"d-liderazgo-m5-l2":[{"tipo":"texto","texto":"Un mando medio toma decenas de decisiones al día. La mayoría son rápidas y reversibles (a quién mover de estación). Algunas son difíciles de deshacer (cambiar un proveedor, proponer a alguien para un ascenso). La regla práctica: <b>decide rápido lo reversible y date más tiempo en lo que no tiene marcha atrás</b>."},{"tipo":"pasos","rotulo":"Método para decisiones importantes","pasos":["<b>Define el problema</b> en una frase. Pregunta «¿por qué?» varias veces (la técnica de los <b>5 porqués</b>, del sistema de producción de Toyota) para llegar a la causa.","<b>Reúne datos</b> suficientes, no todos los posibles.","<b>Genera al menos dos opciones</b>; consulta a quien conoce el tema.","<b>Compara</b> con criterios claros: seguridad, cliente, costo, tiempo, personas.","<b>Decide y comunica</b> el porqué.","<b>Revisa</b> el resultado y aprende."]},{"tipo":"tabla","titulo":"Los 5 porqués: la línea 2 paró","encabezados":["Pregunta","Respuesta"],"filas":[["¿Por qué paró la línea?","Se atoró la banda"],["¿Por qué se atoró?","El rodillo estaba desgastado"],["¿Por qué estaba desgastado?","No se cambió en el mantenimiento preventivo"],["¿Por qué no se cambió?","No había refacción en almacén"],["¿Por qué no había?","Nadie tiene asignado revisar el mínimo de refacciones críticas"]],"nota":"La solución real no es «cambiar el rodillo», es asignar quién revisa el inventario de refacciones críticas."},{"tipo":"texto","texto":"<b>Tu propio estrés.</b> Estás entre la presión de arriba y las necesidades de abajo. Señales de alerta: dormir mal por varias semanas, irritarte con todo, dolores de cabeza o de estómago frecuentes, no desconectarte nunca del celular del trabajo, dejar de hacer lo que antes disfrutabas. Un jefe agotado decide peor y trata peor a su gente."},{"tipo":"lista","items":["Pausas breves: respira lento unos minutos entre juntas.","Límites: acuerda con tu equipo qué es emergencia para llamarte fuera de horario.","Delega y usa la matriz de Eisenhower para soltar lo que no te toca.","Cuida sueño, comida y movimiento; no son lujo, son herramientas de trabajo.","Busca con quién hablar: un colega, tu jefe o un profesional."]},{"tipo":"destacado","texto":"Si el estrés te está rebasando, pide apoyo a tu servicio médico o a un profesional de la salud mental. Si tienes pensamientos de hacerte daño, llama a la <b>Línea de la Vida 800 911 2000</b> (24 horas, gratuita) o al <b>911</b> en una emergencia."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Decidir a quién mover de estación hoy es una decisión…","ops":["Reversible: se decide rápido","Urgente: se decide sin consultar a nadie","Estratégica: la decide la dirección","Irreversible: requiere semanas de análisis"],"correcta":0,"explica":"Es reversible: si sale mal, mañana la cambias. Las decisiones reversibles se toman rápido; el análisis largo es para las irreversibles."},{"p":"Los 5 porqués sirven para…","ops":["Alargar la junta","Llegar a la causa de fondo de un problema","Culpar a alguien"],"correcta":1},{"p":"Revisar mensajes del trabajo a las 2 de la mañana todos los días es…","ops":["Una señal de alerta de estrés","Señal de compromiso sano","Obligatorio para un jefe"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la decisión tomada en caliente</b><br>Un coordinador de logística en Veracruz recibió la queja de un cliente importante: su pedido llegó incompleto. En caliente, despidió al almacenista del turno y cambió de proveedor de transporte. Dos días después se supo que el error venía del sistema de pedidos. Además, llevaba tres semanas durmiendo cinco horas y sin descansos.<br>Rápido en lo reversible; con método en lo que no tiene marcha atrás. Los 5 porqués llevan a la causa de fondo. Un jefe agotado decide y trata peor."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué decisión no tenía marcha atrás?","ops":["El despido del almacenista","Revisar el pedido","Llamar al cliente"],"correcta":0,"explica":"Las decisiones irreversibles piden método."},{"p":"¿Qué habría revelado aplicar los 5 porqués?","ops":["Que el error venía del sistema de pedidos","Que el cliente mentía","Que el almacenista era culpable"],"correcta":0,"explica":"La causa de fondo no siempre es la persona."},{"p":"Su falta de sueño y descanso…","ops":["no tiene relación","es normal en un jefe","afecta su juicio y su trato; debe atenderla y pedir apoyo"],"correcta":2,"explica":"Cuidar tu energía es parte del trabajo."}]},{"tipo":"comparar","titulo":"Cómo se responde a la queja","mal":"«¡Está despedido el del turno y cambiamos de transportista!»","bien":"«Primero: completamos el pedido del cliente hoy. Segundo: revisamos con los 5 porqués dónde falló. Decisiones sobre personas o proveedores, hasta tener la causa.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Aplica los 5 porqués a un problema repetido de un equipo que conozcas hasta encontrar una causa que se pueda corregir.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe tus tres señales personales de estrés y qué harás cuando aparezcan.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Decidir con método y cuidar tu energía","texto":"¿ES REVERSIBLE?\nSí → decide rápido, observa y ajusta.\nNo → datos, 5 porqués, opciones, consulta y luego decide.\n\n5 PORQUÉS: [ ] → [ ] → [ ] → [ ] → [ ]\nCausa de fondo: [ ]\n\nMIS SEÑALES DE ESTRÉS: 1. [ ] 2. [ ] 3. [ ]\nCuando aparezcan: [dormir, pausa, pedir apoyo a ___]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Rápido en lo reversible; con método en lo que no tiene marcha atrás.","Los 5 porqués llevan a la causa de fondo.","Cuida tu energía: un jefe agotado decide y trata peor; pide ayuda a tiempo."]}],"d-liderazgo-m5-l3":[{"tipo":"texto","texto":"Parece contradictorio, pero <b>desarrollar a alguien que pueda hacer tu trabajo</b> es de lo mejor que puedes hacer por tu carrera. Si nadie puede cubrirte, no puedes tomar vacaciones tranquilo, ni capacitarte, ni ser promovido: tu jefe no puede moverte sin dejar un hueco."},{"tipo":"tabla","titulo":"Cómo aprende un adulto en el trabajo (regla práctica 70-20-10)","encabezados":["Proporción aproximada","Cómo","Ejemplo"],"filas":[["70%","Experiencia: retos reales en el trabajo","Que cubra la junta de arranque los viernes"],["20%","Otros: retroalimentación, mentoría, observar","Acompañarte a la junta con producción y comentar después"],["10%","Cursos y lecturas","Un curso de Excel o de seguridad industrial"]],"nota":"Los porcentajes son una guía, no una ley: la idea es que la mayor parte del desarrollo pasa haciendo, con acompañamiento."},{"tipo":"pasos","rotulo":"Plan para desarrollar a tu posible reemplazo","pasos":["Elige a alguien con <b>capacidad y ganas</b> (no solo al más antiguo) y pregúntale si le interesa.","Lista las tareas de tu puesto y marca cuáles ya domina y cuáles no.","Asígnale tareas graduales: primero te observa, luego lo hace contigo, luego solo con revisión, luego solo.","Da retroalimentación SBI después de cada tarea nueva.","Hazlo visible: dile a tu jefe quién te puede cubrir y en qué.","Revisa el avance cada mes en su junta 1 a 1."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Desarrollar a tu reemplazo…","ops":["Pone en riesgo tu puesto siempre","Es tarea exclusiva de RH","Facilita que te puedan promover o que tomes vacaciones"],"correcta":2,"explica":"Un jefe sin respaldo es difícil de mover."},{"p":"Según la regla 70-20-10, la mayor parte del aprendizaje viene de…","ops":["Los libros","La experiencia en retos reales","Los cursos"],"correcta":1},{"p":"Para elegir a quién desarrollar el criterio principal es…","ops":["Capacidad y ganas","Antigüedad solamente","Amistad"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la secuencia","items":[{"frase":"Primero te observa, luego lo hace ___, luego solo con revisión.","resp":["contigo"]},{"frase":"El avance se revisa cada mes en la junta ___.","resp":["1 a 1","uno a uno"]}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el jefe al que no podían promover</b><br>Andrea era la mejor jefa de turno de un hotel en Puerto Vallarta. Cuando se abrió la gerencia, no la promovieron: «si te subimos, nadie puede hacer tu trabajo». Ella hacía todo sola porque «era más rápido». Otro jefe, con menos resultados, sí subió porque tenía a alguien listo para reemplazarlo.<br>Si nadie puede cubrirte, nadie puede promoverte. El 70-20-10: la mayor parte del desarrollo pasa haciendo, con acompañamiento. Delega en forma gradual y hazlo visible con tu jefe."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Por qué no promovieron a Andrea?","ops":["Porque tenía malos resultados","Porque no quería","Porque no había desarrollado a nadie para cubrirla"],"correcta":2,"explica":"Sin reemplazo, subirla deja un hueco."},{"p":"Según el 70-20-10, la mayor parte del aprendizaje viene de…","ops":["cursos","leer manuales","hacer el trabajo con retos reales"],"correcta":2,"explica":"70% experiencia, 20% relaciones, 10% formación formal."},{"p":"¿Cómo hacer visible el desarrollo de tu reemplazo?","ops":["No hace falta","Hacerlo en secreto","Contarle a tu jefe los avances y dejar que la persona presente resultados"],"correcta":2,"explica":"Tu jefe necesita ver que hay alguien listo."}]},{"tipo":"comparar","titulo":"Cómo se oye con el posible reemplazo","mal":"«Mejor lo hago yo, es más rápido.»","bien":"«Este mes tú haces la programación de turnos; yo la reviso contigo el jueves. En tres meses quiero que la hagas sola y la presentes al gerente.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Elige a una persona de un equipo que conozcas que podría ser reemplazo del jefe y escribe su plan de desarrollo de seis meses con el 70-20-10.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe qué tareas le soltarías primero y cómo lo comunicarías a tu jefe.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Plan de desarrollo del reemplazo","texto":"PLAN DE DESARROLLO — [Persona]\nMeta: cubrir mi puesto en [meses]\n70% Hacer: [tareas que irá asumiendo, de menor a mayor responsabilidad]\n20% Aprender de otros: [a quién acompaña, con quién platica]\n10% Formación: [curso, lectura]\nRevisión mensual: [fecha]\nComunicación a mi jefe: [cuándo y cómo]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Si nadie puede cubrirte, nadie puede promoverte.","70-20-10: la mayor parte del desarrollo pasa haciendo, con acompañamiento.","Delega en forma gradual y hazlo visible con tu jefe."]}],"d-liderazgo-m5-l4":[{"tipo":"texto","texto":"Los primeros meses en un puesto de mando marcan cómo te verá tu equipo. <b>Michael Watkins</b>, en <i>The First 90 Days</i> (2003), plantea que en una transición conviene aprender rápido, conseguir algunas victorias tempranas y alinear expectativas con tu jefe. Aunque ya lleves tiempo como jefe, un plan de 90 días te sirve para reiniciar con intención."},{"tipo":"tabla","titulo":"Estructura sugerida","encabezados":["Periodo","Enfoque","Acciones"],"filas":[["Días 1 a 30","Escuchar y entender","1 a 1 con cada persona; revisar indicadores; acordar con tu jefe qué espera de ti"],["Días 31 a 60","Ordenar","Objetivos SMART del equipo; junta de arranque diaria; semáforo en Excel; delegar 2 tareas"],["Días 61 a 90","Consolidar y desarrollar","Primer cambio de mejora; reconocimiento sistemático; elegir y empezar a desarrollar a tu posible reemplazo"]]},{"tipo":"plantilla","rotulo":"Mi plan de liderazgo de 90 días","texto":"MI PLAN DE LIDERAZGO DE 90 DÍAS\nNombre: [...]      Puesto: [...]      Equipo: [número de personas]\nFecha de inicio: [...]      Revisión con mi jefe: [día 30, 60 y 90]\n\nLo que mi jefe espera de mí (en sus palabras): [...]\n\nDÍAS 1 A 30 — ESCUCHAR Y ENTENDER\n- Juntas 1 a 1 con: [nombres]\n- Indicadores que voy a revisar: [cumplimiento, calidad, asistencia...]\n- Lo que aprendí (llenar el día 30): [...]\n\nDÍAS 31 A 60 — ORDENAR\n- Objetivo SMART del equipo: [...]\n- Tareas que voy a delegar y a quién (nivel): [...]\n- Hábito nuevo: [junta de arranque, semáforo semanal...]\n\nDÍAS 61 A 90 — CONSOLIDAR Y DESARROLLAR\n- Victoria temprana que busco: [...]\n- Persona que voy a desarrollar y primeras tareas: [...]\n- Cómo voy a reconocer al equipo: [...]\n\nMi compromiso personal (estilo, comunicación, energía): [...]"},{"tipo":"relacionar","rotulo":"¿En qué etapa va cada acción?","pares":[["Tener una 1 a 1 con cada colaborador","Días 1 a 30"],["Definir el objetivo SMART del equipo","Días 31 a 60"],["Empezar a desarrollar a tu posible reemplazo","Días 61 a 90"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En los primeros 30 días lo prioritario es…","ops":["Cambiar todos los procesos","Despedir a quien no rinde","Escuchar y entender al equipo y lo que espera tu jefe"],"correcta":2,"explica":"Cambiar sin entender genera resistencia y errores."},{"p":"Una «victoria temprana» es…","ops":["Ganar una discusión","Una mejora visible y alcanzable que da confianza al equipo","Un proyecto enorme a cinco años"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"Después de este diplomado, ¿cuál es la <b>única</b> conducta de liderazgo que vas a empezar a practicar el próximo lunes? Escribe cuándo, con quién y cómo sabrás que la estás cumpliendo.","ayuda":"A partir del lunes voy a… con… Sabré que lo cumplo porque…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el plan que se quedó en buenas intenciones</b><br>Un supervisor de un centro de distribución en Monterrey terminó un curso de liderazgo muy motivado. Escribió «voy a escuchar más, retroalimentar más y delegar más». A los tres meses no había cambiado nada: no tenía fechas, ni conductas concretas, ni había hablado con su jefe.<br>Un plan de 90 días tiene etapas: escuchar y entender, ordenar, consolidar y desarrollar. Alinea expectativas con tu jefe y busca victorias tempranas. El liderazgo se construye con conductas pequeñas y constantes."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué le faltó al plan?","ops":["Un curso más","Más motivación","Conductas concretas, fechas y acuerdo con su jefe"],"correcta":2,"explica":"«Escuchar más» no dice qué harás el lunes."},{"p":"Una conducta concreta sería…","ops":["«Juntas 1 a 1 de 20 minutos con cada persona cada dos semanas»","«Ser mejor jefe»","«Escuchar más»"],"correcta":0,"explica":"Se puede verificar en la agenda."},{"p":"¿Por qué alinear el plan con el jefe?","ops":["Para acordar prioridades y que te apoye","No hace falta","Para que te felicite"],"correcta":0,"explica":"Sin su acuerdo, tus prioridades pueden chocar con las suyas."}]},{"tipo":"comparar","titulo":"Cómo se escribe el compromiso","mal":"«Voy a escuchar más.»","bien":"«Desde el lunes 3: junta 1 a 1 de 20 minutos con cada uno de mis 8 colaboradores cada dos semanas, con agenda fija. Lo reviso con mi jefe el último viernes del mes.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe cinco conductas pequeñas y verificables que mejorarían tu liderazgo (o el de un jefe que conozcas) y cuándo empezaría cada una.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe la conversación que tendrías con tu jefe para alinear tu plan de 90 días.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Plan de liderazgo de 90 días (resumen)","texto":"PLAN DE 90 DÍAS\nDías 1–30 Escuchar y entender: [ ]\nDías 31–60 Ordenar: [metas SMART, tablero, 1 a 1]\nDías 61–90 Consolidar y desarrollar: [delegación, reemplazo]\nVictoria temprana: [ ]\nConductas semanales: [ ]\nAcuerdo con mi jefe: [fecha]\nCómo sabré que funcionó: [indicadores]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Un plan de 90 días: escuchar y entender, ordenar, consolidar y desarrollar.","Alinea expectativas con tu jefe y busca victorias tempranas.","El liderazgo se construye con conductas pequeñas y constantes."]}],"d-liderazgo-m5-lab":[{"tipo":"destacado","texto":"Este es tu proyecto final. Vas a armar tu <b>plan de liderazgo de 90 días</b> para el equipo que diriges hoy o, si aún no diriges, para un equipo que conozcas bien o que te gustaría dirigir. Al terminar tendrás un plan concreto para aplicar el lunes o mostrar en una entrevista para un puesto de mando."},{"tipo":"texto","texto":"<p><b>Parte 1 — Diagnóstico.</b> Con lo del módulo 1.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 1","pregunta":"Describe el equipo, tu mapa situacional por persona y los errores de jefe nuevo que vas a evitar.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 2 — Comunicación.</b> Con lo del módulo 2.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 2","pregunta":"Escribe tu formato de junta de arranque, tu rutina de reconocimiento SBI y una conversación difícil que tengas pendiente, preparada.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 3 — Organización y medición.</b> Con lo del módulo 3.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 3","pregunta":"Escribe los objetivos SMART del equipo, el tablero con semáforo, tu rutina de 1 a 1 y qué vas a delegar.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 4 — Personas, cambio y desarrollo.</b> Con lo de los módulos 4 y 5.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 4","pregunta":"Escribe cómo cuidarás la seguridad psicológica y tu papel ante la NOM-035, un cambio que vas a liderar, tu plan para desarrollar a tu reemplazo y el calendario de 90 días.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"El estilo de liderazgo se elige…","ops":["según tu personalidad","por persona y por tarea","una vez y para siempre"],"correcta":1,"explica":"Liderazgo situacional."},{"p":"Una retroalimentación SBI tiene…","ops":["solo la crítica","saludo, crítica y despedida","situación, comportamiento e impacto"],"correcta":2,"explica":"Hechos, no juicios."},{"p":"Si una persona no cumple porque no sabe hacerlo, la respuesta es…","ops":["capacitar y acompañar","despedir","sancionar"],"correcta":0,"explica":"El diagnóstico define la acción."},{"p":"Ante una posible situación de acoso en el equipo…","ops":["lo median entre ellos","lo ignoras","canalizas a RH y proteges a quien reporta"],"correcta":2,"explica":"El acoso no se media."},{"p":"Tu constancia de este diplomado…","ops":["es una certificación oficial de competencias","es un título de licenciatura","es de Instituto Mara, no documento SEP ni CONOCER"],"correcta":2,"explica":"Dilo así en tu CV."}]},{"tipo":"plantilla","rotulo":"Índice del plan de liderazgo de 90 días","texto":"PLAN DE LIDERAZGO — 90 DÍAS\n[Equipo] · [Tu nombre] · [Fecha]\n\n1. Diagnóstico del equipo y mapa situacional\n2. Acuerdos y expectativas con mi jefe\n3. Rutinas de comunicación: arranque, SBI, 1 a 1\n4. Objetivos SMART y tablero del equipo\n5. Delegación y prioridades\n6. Clima: reconocimiento, conflictos, seguridad psicológica y NOM-035\n7. Cambio que voy a liderar\n8. Desarrollo de mi reemplazo\n9. Cuidado de mi energía\n10. Calendario de 90 días e indicadores","nota":"Úsala como índice de tu proyecto final."}]},"q":{"d-liderazgo-m1":[{"p":"La principal diferencia entre un operativo y un mando medio es que el mando medio…","ops":["Trabaja más horas","Ya no tiene jefe","No necesita conocer a fondo el trabajo del área","Logra resultados a través de su equipo"],"correcta":3},{"p":"La constancia de este diplomado la emite…","ops":["CONOCER, como estándar de competencia","La STPS","Instituto Mara, como diplomado libre","La SEP"],"correcta":2},{"p":"El liderazgo, a diferencia de la autoridad formal…","ops":["No se puede aprender","Se gana con conducta y trato justo","Se obtiene con el nombramiento y el puesto","Solo se usa en emergencias"],"correcta":1},{"p":"En una emergencia de seguridad, el estilo más adecuado es…","ops":["Directivo","Delegativo","Participativo con votación","Ninguno"],"correcta":0},{"p":"El modelo situacional fue propuesto por…","ops":["Peter Drucker","Amy Edmondson","Frederick Herzberg y Douglas McGregor","Paul Hersey y Ken Blanchard"],"correcta":3},{"p":"Para una persona capaz y comprometida con la tarea, el modelo situacional recomienda…","ops":["Persuadir","Supervisar cada paso","Delegar","Dirigir"],"correcta":2},{"p":"Delegar una tarea compleja a alguien que nunca la ha hecho es…","ops":["Liderazgo participativo","Abandonarlo: primero hay que dirigir o entrenar","La mejor forma de motivarlo, porque así aprende solo y rápido","Lo que pide el modelo"],"correcta":1},{"p":"Un error típico del jefe nuevo es…","ops":["Seguir haciendo el trabajo operativo en lugar de organizar y enseñar","Escuchar a su equipo","Pedir orientación a su jefe","Aplicar las mismas reglas a todos desde el primer día, incluidos sus antiguos compañeros de área"],"correcta":0}],"d-liderazgo-m2":[{"p":"Una junta de arranque de turno efectiva dura aproximadamente…","ops":["Una hora","Lo que haga falta","Dos minutos sin agenda","10 minutos"],"correcta":3},{"p":"¿Cuál es una instrucción clara?","ops":["«Hagan lo que puedan»","«Ya saben qué hacer»","«Luis, termina el conteo del pasillo 7 antes de las 2 con la hoja nueva y avísame si hay diferencias»","«Por favor, apóyenme todos con el inventario en cuanto puedan; es muy importante que quede bien y a tiempo»"],"correcta":2},{"p":"Parafrasear consiste en…","ops":["Terminar la frase del otro","Repetir con tus palabras lo que entendiste para confirmarlo","Cambiar de tema","Dar tu opinión de inmediato sobre lo que dijo para no perder tiempo"],"correcta":1},{"p":"Al plantear un problema a tu jefe conviene llevar…","ops":["Hechos, impacto y una propuesta","Solo tu queja","Rumores del equipo","Solo el problema, para que él decida cómo resolverlo"],"correcta":0},{"p":"En el modelo SBI, la «B» (comportamiento) debe ser…","ops":["Una opinión sobre la personalidad","Un rumor","Una amenaza","Observable y sin juicios"],"correcta":3},{"p":"«Eres un irresponsable» es…","ops":["Un impacto","Una situación","Un juicio sobre la persona, no un comportamiento","Un buen ejemplo de retroalimentación directa y sin rodeos"],"correcta":2},{"p":"La retroalimentación de mejora se da preferentemente…","ops":["Meses después, en la evaluación anual","En privado y pronto","Frente a todo el equipo","Por el grupo de WhatsApp"],"correcta":1},{"p":"Una conversación difícil debe terminar con…","ops":["Un acuerdo concreto y fecha de seguimiento","Un regaño fuerte","Nada en particular","Una advertencia clara de lo que pasará si no cambia"],"correcta":0}],"d-liderazgo-m3":[{"p":"¿Cuál es un objetivo SMART?","ops":["Mejorar la calidad","Mejorar notablemente la calidad de la línea 3 durante todo este año","Ser los mejores","Bajar el rechazo de la línea 3 de 2.5% a 1.5% al 31 de diciembre"],"correcta":3},{"p":"Decir «resuélvelo y me cuentas cómo quedó» corresponde al nivel de delegación…","ops":["Recomienda","Yo decido todo","Actúa y avísame después","Investiga y me informas antes de actuar"],"correcta":2},{"p":"En la matriz de Eisenhower, capacitar a tu equipo suele ser…","ops":["Siempre urgente","Importante y no urgente: se agenda","Urgente y no importante: se delega a otro","Algo que se elimina"],"correcta":1},{"p":"Si la meta es 1,000 piezas y alguien hizo 870, su cumplimiento es…","ops":["87%","113%","13%","870%"],"correcta":0},{"p":"La fórmula =CONTAR.SI(B2:B7,\">=1\") sirve para…","ops":["Sumar las piezas","Sacar el promedio","Encontrar el valor mínimo de cumplimiento en la columna B","Contar cuántas personas llegaron al 100% o más"],"correcta":3},{"p":"El % de ausentismo se calcula como…","ops":["Faltas por 24","Personas entre faltas","Faltas entre días programados","Días programados entre número de faltas"],"correcta":2},{"p":"Antes de aplicar una consecuencia por bajo desempeño debes revisar…","ops":["Nada, basta el indicador","Si la persona sabe qué se espera, sabe hacerlo y puede hacerlo","Solo su actitud","Qué opinan sus compañeros y su jefe anterior sobre su desempeño"],"correcta":1},{"p":"Sobre un plan de mejora, lo correcto es…","ops":["Trabajarlo con RH; las sanciones o rescisiones no las decide el jefe por su cuenta","Usarlo para documentar las faltas y despedir de inmediato si la persona no mejora en un mes","Hacerlo de palabra, sin registro","Aplicarlo sin avisar a la persona"],"correcta":0}],"d-liderazgo-m4":[{"p":"Según Herzberg, el reconocimiento y el logro son factores…","ops":["Higiénicos","Legales","Irrelevantes","Motivadores"],"correcta":3},{"p":"Un reconocimiento eficaz es…","ops":["Siempre en dinero","Igual para todos sin importar lo que hicieron","Concreto, oportuno y sincero","Genérico y una vez al año"],"correcta":2},{"p":"Buscar juntos una solución que sirva a ambas partes es…","ops":["Ceder","Colaborar","Competir por la mejor opción","Evitar"],"correcta":1},{"p":"Si una trabajadora reporta insinuaciones sexuales de un compañero, el jefe…","ops":["Escucha y canaliza a RH según el protocolo","Los pone a mediar","Le pide que lo ignore","Lo comenta en la junta para que no se repita"],"correcta":0},{"p":"La seguridad psicológica, según Amy Edmondson, es…","ops":["Que no haya exigencia","Tener seguro de gastos médicos mayores, protocolos de protección civil y equipo de seguridad","No cometer errores","La creencia de que es seguro hablar, preguntar y admitir errores en el equipo"],"correcta":3},{"p":"Exigir certificado de no embarazo para contratar o ascender está…","ops":["Obligatorio","Permitido solo en planta","Prohibido por la LFT","Permitido si lo pide el jefe"],"correcta":2},{"p":"Entre los factores de riesgo psicosocial de la NOM-035 está…","ops":["El número de sucursales, el tamaño de la empresa y su antigüedad","El liderazgo negativo y las relaciones negativas en el trabajo","El color de las paredes","La marca del uniforme"],"correcta":1},{"p":"Ante una falta grave de un colaborador, el jefe debe…","ops":["Documentar los hechos y llevar el caso a RH","Despedirlo en ese momento","Pedirle que firme su renuncia para evitar problemas","No hacer nada"],"correcta":0}],"d-liderazgo-m5":[{"p":"La resistencia al cambio suele deberse a…","ops":["La pereza","La edad","El salario y las prestaciones, únicamente, en casi todos los casos","El miedo a perder algo y no entender el porqué"],"correcta":3},{"p":"Las etapas del cambio según Kurt Lewin son…","ops":["Negar, aceptar, olvidar","Urgencia, visión, comunicación y cultura","Descongelar, cambiar y recongelar","Planear, hacer, verificar"],"correcta":2},{"p":"Antes de exigir un nuevo procedimiento, el jefe debe…","ops":["Evitar hablar del tema","Capacitar al equipo","Sancionar a quien se equivoque","Esperar a que aprendan solos"],"correcta":1},{"p":"La técnica de los 5 porqués sirve para…","ops":["Encontrar la causa de fondo de un problema","Asignar culpables","Evaluar el desempeño de cada persona del equipo","Calcular metas"],"correcta":0},{"p":"Una decisión reversible y de bajo impacto conviene tomarla…","ops":["Después de semanas de análisis","Nunca","Siempre por votación","Rápido"],"correcta":3},{"p":"Una señal de alerta de estrés propio es…","ops":["Delegar tareas","Hacer pausas breves durante la jornada y caminar un poco","Dormir mal por semanas y no desconectarte del trabajo","Tomar vacaciones"],"correcta":2},{"p":"Desarrollar a tu reemplazo…","ops":["Está prohibido","Facilita que te promuevan o te puedan cubrir","Te pone en riesgo, porque la empresa puede reemplazarte","Solo le corresponde a RH"],"correcta":1},{"p":"En los primeros 30 días de un plan de liderazgo lo principal es…","ops":["Escuchar y entender","Cambiar todo","Despedir a alguien","Comprar equipo nuevo"],"correcta":0}]}});
